const MAX_FIX_ROUNDS = (args && args.maxFixRounds) || 2
const LIBRARY = [{"key": "ui-kit", "owns": ["src/ui-kit/", "src/app/sandbox/pages/ui-kit.tsx"], "brief": "Build the Lumen DESIGN SYSTEM that every scene, mini-game and engagement system will use. Keep every existing export of src/ui-kit/context.tsx working (ServicesProvider, useServices, useSignal, useRegistry, asComponent, HudSlot) \u2014 you may add to it.\n\n1) CSS: tokens.css + base.css imported from src/ui-kit/index.ts. Tokens as CSS custom properties: palette from GAME_DESIGN.md \u00a73 (ink/aubergine backgrounds, candle gold, ivory text, muted, system accents, clinical normal/abnormal/critical), typography (Fraunces Variable display, Inter Variable UI, Space Grotesk numbers \u2014 fonts are already loaded by the app), type scale, spacing scale, radii, layered shadows & glows, glass surface recipe (backdrop-filter, luminous 1px borders, inner highlight), easing curves (out-expo, spring overshoot), durations, z-index layers. html.high-contrast and html.reduced-motion variants + prefers-reduced-motion. base.css: reset, body background, custom scrollbars, gorgeous focus-visible rings, ::selection, utility classes kept minimal.\n\n2) Components (Preact, typed props, accessible, each with hover/press/focus states and micro-animations): Button (variants: primary-gold, glass, ghost, danger; sizes; leading icon; loading; satisfying press), IconButton, GlassPanel/Card (optional accent glow, header slot), Modal/Dialog (portal-less overlay, focus trap, Esc, animated scale+blur in), Tabs, Chip, Badge, ProgressBar & RingMeter (animated fill), CountUp (animated number, Space Grotesk), Stars (0-3 with fill animation), GradeStamp (S/A/B/C/D/F \u2014 dramatic rubber-stamp slam animation, S is iridescent gold), Tooltip, ToastHost (listens to services.bus 'toast' events, stacks, auto-dismiss, tone colours), RewardChip (renders a RewardGrant with rarity glow: common/rare/epic/legendary), SpeechBubble with typewriter text reveal (skippable on click), Ornament/Divider (gold filigree SVG), Kbd, ScrollArea, Screen layout (fixed full-viewport scene frame with top bar: left/right HudSlot areas + title + back button), and Backdrop: an animated scene background (night gradient, slow drifting light motes/bokeh on a canvas, optional rain-on-glass streaks, film grain overlay, vignette) with variants 'title' | 'hub' | 'exam' | 'emergency' | 'results' | 'calm'; must be cheap (pause when hidden, DPR-aware, reduced-motion = static).\n\n3) Icon: an <Icon name=... /> component with a cohesive hand-tuned SVG line-icon set (1.75px strokes, rounded) covering: each TestId in core/tests.ts (visual-acuity chart, pinhole, retinoscope, phoropter, keratometer, penlight/pupils, occluder/cover-test, motility H, convergence, colour plate, amsler grid, visual field, slit lamp, fluorescein drop, tonometer, ophthalmoscope) plus UI icons: coin, gem, star, trophy, flame, clock, heart, lock, unlock, chevron-left/right, close, check, x, settings, sound-on, sound-off, gift, crate, eye, chart, user, users, crown, lightning, sparkle, book, play, pause, refresh, info, warning, alert. Export the icon name union type.\n\n4) Hooks: useSfx() that returns a play(id) function using services.audio when inside a ServicesProvider and a no-op otherwise; useReducedMotion(); useInterval/useAnimationFrame helpers that clean up.\n\n5) Sandbox page src/app/sandbox/pages/ui-kit.tsx (default export { id: 'ui-kit', title, component }) showcasing every component and the icon grid on top of the Backdrop \u2014 this is how reviewers judge you; make it look like a premium design-system showcase. View it at ?sandbox=page/ui-kit. Keep each component in its own file under src/ui-kit/components/. Export everything from src/ui-kit/index.ts.", "tier": "standard", "start": "review"}, {"key": "audio", "owns": ["src/audio/", "src/app/sandbox/pages/audio.tsx"], "brief": "Implement createAudio(): AudioPort in src/audio (keep that export name/signature) \u2014 a fully PROCEDURAL WebAudio engine (no audio files). Requirements:\n- Every SfxId in src/core/ports.ts gets a distinct, premium, cohesive sound designed with oscillators, FM, filtered noise, envelopes, convolution/feedback-delay shimmer: think glass chimes, brass instruments, soft clicks, warm coins, magical sparkles. 'lens-click' and 'dial' should feel like precise optical hardware; 'coin(s)' satisfying; 'levelup'/'legendary'/'rare' escalating fanfares; 'fail'/'error' gentle but clear (never harsh); 'heartbeat' and 'alarm' for emergencies; 'countdown'/'tick' for timers; 'stamp' for the grade stamp; 'door' for a patient entering; 'streak-fire' whooshy; 'chest-open' anticipatory. Musical: tune pitched sounds to one key (e.g. D major / D lydian) so they harmonise with music.\n- play(id, {volume, pitch}) with small random pitch/volume variation to avoid fatigue, voice limiting (max simultaneous instances per id), and a tiny cooldown for spammy ids like 'hover'.\n- music(track | null): generative, endlessly varying ambient music per TrackId \u2014 title (wondrous: lush detuned pads, celesta/glass arpeggios, slow evolving chords), hub (warm lo-fi clinic: soft keys, gentle pulse), exam (focused, minimal, light pulse), emergency (tense: low drone, heartbeat kick, rising filter), results (triumphant shimmer), zen (soft, sparse). Smooth 1.5-2s crossfades between tracks; schedule with the AudioContext clock (lookahead scheduler), not setInterval jitter. Keep CPU low.\n- setVolumes({master,sfx,music}) with smooth gain ramps; unlock() resumes the context on the first user gesture; music requested before unlock starts once unlocked.\n- Must be completely safe where AudioContext is missing (happy-dom tests, old browsers): degrade to no-ops, never throw. Pause music when document is hidden.\n- Structure: engine/context management, sfx library (one small file per family is fine), music engine (instruments + sequencer + per-track compositions), a mixer. Unit-test the pure parts (scales, note math, scheduler logic, voice limiting) with vitest.\n- Sandbox page src/app/sandbox/pages/audio.tsx (default export { id: 'audio', title, component: (p:{services}) => ... }) \u2014 a beautiful little mixing-desk page: buttons to audition every SFX and every music track, volume sliders. Note: the sandbox passes `services` whose audio is the real createAudio() instance, so drive it via props.services.audio. Reviewers cannot hear audio; they will judge the code (sound design quality, scheduling correctness) and the page visuals.", "tier": "standard", "start": "build"}, {"key": "render-fx-avatar", "owns": ["src/render/fx/", "src/render/avatar/", "src/app/sandbox/pages/render-fx.tsx", "src/app/sandbox/pages/render-avatar.tsx"], "brief": "Two shared rendering libraries (src/render/index.ts already re-exports ./fx and ./avatar \u2014 keep the createFx signature exactly).\n\nA) FX \u2014 createFx(layer: HTMLElement, shakeTarget: HTMLElement, opts: { reducedMotion: () => boolean }): FxPort (contract in src/core/ports.ts). A full-screen canvas inside `layer` (DPR-aware, resizes, RAF only while particles are alive). Pooled particle system with gravity/drag/rotation/fade; kinds: confetti (tumbling ribbons in palette colours), sparks (additive glowing streaks), coins (spinning gold coins with highlight that arc and fall), stars (twinkling 4-point stars), hearts, embers (rising glowing motes). burst(x,y,{kind,count,color}). floatText: DOM element rising + fading with Space Grotesk numbers and glow. shake(strength, ms): decaying perlin/noise translate+rotate on shakeTarget (restore transform exactly). flash(color, ms) full-screen additive flash. vignette(color, ms) pulsing edge glow. hitstop(ms): freeze particle sim and add a brief CSS class 'fx-hitstop' on shakeTarget (e.g. tiny scale punch). Reduced motion: no shake, no flash, 30% particles. Clean, framework-free TS.\n\nB) AVATAR \u2014 gorgeous procedural patient portraits. Export a Preact component <PatientAvatar spec={AvatarSpec} age sex expression? external? lookAt? size? animated? /> and a pure function generateAvatar(rng: Rng, opts: { age: number; sex: 'F'|'M'|'X' }): AvatarSpec. Style: premium editorial vector illustration (think high-end flat illustration with soft gradient shading, rim light from a gold key light, subtle texture) \u2014 head, neck, shoulders/outfit, hair styles (all HairStyle values), facial hair, headwear, glasses styles, accessories, skin tones 0-5 (diverse, respectful), age cues (laugh lines, wrinkles, grey/white hair, age spots at 70+; children look young). Eyes are expressive with the spec's iris colour, pupils, eyelids that BLINK, gaze that follows lookAt (x,y in -1..1). Expressions: 'neutral' | 'worried' | 'pain' | 'happy' | 'relieved' | 'squint' | 'surprised' (eyebrows, mouth, eyelids). Idle animation: breathing (shoulders), micro head sway, randomised blinks (respect reduced motion via prop). Clinical visible signs from external (PatientFindings['external']): redEye per eye (injected sclera), tearing (glistening tear streak), ptosis (droopy lid on that side), proptosis, squinting, eyePatch, photophobia (shielding hand or squint), forehead dermatomal rash (shingles), plus optional strabismus prop { eye: 'OD'|'OS', direction: 'in'|'out'|'up'|'down' } to turn one eye. Remember OD = patient's RIGHT eye = viewer's LEFT. SVG output, scalable, crisp. Also export a small <AvatarBust/> variant for list rows/leaderboards (just head, circular crop, ring colour).\n\nSandbox pages: render-fx.tsx (buttons triggering every FX on a backdrop; click anywhere bursts) and render-avatar.tsx (a grid of ~16 generated patients of all ages/tones + a detailed panel with toggles for each expression and clinical sign). Each default export { id, title, component }. Unit-test generateAvatar determinism & validity.", "tier": "standard", "start": "review"}, {"key": "render-eye-fundus", "owns": ["src/render/eye/", "src/render/fundus/", "src/app/sandbox/pages/render-eye.tsx", "src/app/sandbox/pages/render-fundus.tsx"], "brief": "Two shared, clinically faithful canvas renderers used by many mini-games (slit lamp, pupils, cover test, tonometry, fluorescein, ophthalmoscopy, retinoscopy) and by the iris collection gallery. src/render/index.ts already re-exports ./eye and ./fundus.\n\nA) EYE CLOSE-UP \u2014 export `type EyeState`, `drawEye(ctx: CanvasRenderingContext2D, w: number, h: number, s: EyeState, t?: number)`, `eyeStateFromFindings(f: PatientFindings, eye: Eye, opts?): EyeState`, and a Preact `<EyeCanvas state={EyeState} width height />` (DPR aware, optional RAF animation for micro-saccades/tear film shimmer). EyeState covers: eye ('OD'|'OS' for nasal/temporal orientation), irisColor, irisSeed, pupilMm (scaled realistically to an ~11.5mm cornea), gaze {x,y}, lidAperture 0..1 (blink/ptosis), lighting 'room'|'penlight'|'slit'|'cobalt'|'dim', redness 0..1 with pattern 'diffuse'|'ciliary-flush'|'sectoral', subconjunctival hemorrhage, chemosis, pinguecula/pterygium (nasal), corneal edema/haze, dendrite, ulcer/infiltrate (white opacity), keratic precipitates, abrasion, foreign body, hypopyon, hyphema, AC depth (affects a van Herick slit view), lens opacity 0..1 with type nuclear(yellow-brown)/cortical(spokes)/PSC, fluorescein stain pattern (all StainPattern values: rendered bright green ONLY under cobalt light), corneal light reflex (Hirschberg) position. Iris must be STUNNING and anatomical: radial fibres, collarette, crypts, pupillary ruff, limbal ring, subtle heterochromia flecks, wet specular highlights and window reflections; plus a dark-iris variant. Also export `paintIrisArt(ctx, size, seed: number, opts: { palette: string[]; rarity: 'common'|'rare'|'epic'|'legendary' })` that paints a jewel-like, collectible iris card artwork (rarer = more exotic palettes, iridescent shimmer, stars in the pupil, etc.) for the Gallery system.\nSlit-lamp support: `drawSlitSection(ctx, w, h, s: EyeState, beam: { x: number; width: number; angleDeg: number; height?: number })` rendering the optical section (corneal parallelepiped, AC gap per van Herick grade, anterior chamber cells as tiny drifting specks and flare as a hazy beam per SUN grade, lens section).\n\nB) FUNDUS \u2014 export `paintFundus(ctx, w, h, post: PosteriorSegment, opts: { eye: Eye; seed: number; redFree?: boolean; view?: { cx: number; cy: number; zoom: number } }): FundusMap` where FundusMap gives NORMALISED (0..1) positions/radii of disc, cup, macula/fovea and every rendered lesion { type, zone, x, y, r } for hit-testing by an ophthalmoscopy spot-the-finding mini-game. Must look like a real fundus photograph: orange-red choroidal glow with radial falloff and vignette, fundusTone (light/medium/dark/tigroid choroidal vessels), correct anatomy for OD vs OS (disc nasal to fovea \u2014 OD disc on the viewer's right? CHECK: in a fundus photo of the RIGHT eye the disc appears on the RIGHT side of the image; left eye on the left), disc ~1.5mm with neuroretinal rim + cup sized by CDR, rim thinning per ISNT violations, pallor, blurred/elevated margins and disc edema (obscured vessels at margin), disc hemorrhage, procedural vascular arcades branching from the disc (arteries thinner and lighter red with central light reflex; veins darker/wider; AV ratio; AV nicking at crossings; copper wiring; tortuosity; venous dilation), macula darker with foveal light reflex. Every LesionType in core/clinical.ts rendered convincingly in its zone with density: dot-blot & flame hemorrhages, microaneurysms, cotton-wool spots, hard exudates (incl. circinate/macular star), drusen small/large, geographic atrophy, subretinal hemorrhage, neovascularization (fine frond vessels at disc/elsewhere), retinal tear (horseshoe), lattice, nevus, pigment clumping, laser scars, Hollenhorst plaque, retinal whitening, cherry-red spot, macular edema (sheen), ERM (wrinkle), macular hole, venous beading. Retinal detachment: grey-white elevated undulating retina with folds in the specified zones, macula-on/off. Vitreous haze/hemorrhage/Weiss ring as an overlay option. Deterministic per seed. Also a Preact `<FundusView post eye seed lensView? />` with drag-to-pan/zoom and an optional ophthalmoscope 'light circle' mask (dark outside a movable circle) used by ophthalmoscopy.\n\nSandbox pages render-eye.tsx and render-fundus.tsx (default export { id, title, component }): galleries of presets (normal, cataract, acute angle closure, uveitis, conjunctivitis, abrasion under cobalt, dendrite, pterygium; fundus: normal OD/OS, glaucoma CDR 0.8 inferior thinning, NPDR, PDR, hypertensive, dry & wet AMD, CRAO, CRVO, RD macula-off, papilledema, tigroid myope) plus a control panel. Accuracy matters: a practising optometrist will judge these images. Unit-test FundusMap geometry (disc side per eye, CDR) and determinism.", "tier": "heavy", "start": "review"}, {"key": "learning-modes", "owns": ["src/learning/", "src/modes/", "src/app/sandbox/pages/modes.tsx"], "brief": "A) LEARNING (src/learning, keep exports createLearning(save, now): LearningPort and attachLearning(services): () => void). Implement an SM-2-style spaced repetition scheduler per DiagnosisId persisted in save slot 'learning' (ease factor, interval, repetitions, due timestamp, lapses, last quality, seen count). record(id, quality 0..5), due(limit) (most overdue first), mastery(id) 0..1 (blend of repetitions, ease, recency; 1 only after several spaced successes), stats() {seen, mastered (mastery>=0.8), due}. attachLearning subscribes to 'case:completed' and records the correct diagnosis with learningQuality(score) (from @core), and when the player picked a WRONG diagnosis also records a small lapse against the diagnosis they confused it with (so confusions resurface); emits 'learning:reviewed'. Thorough vitest tests with an injected clock.\n\nB) MODES (src/modes/<id>/index.ts, each default-exports a ModeModule; one folder each; they must not import each other \u2014 shared logic comes from @core: pickCase, dayKey, createRng). Implement: 'shift' (Clinic Shift: 5 patients, difficulty window ramps with experience \u2014 track completed-case count in a save slot 'mode:shift' or use services.learning.stats(); first ever shift should start gentle, difficulty 1-2), 'rush' (Rush Hour: endless, lives 3, scoreMultiplier ~1.0 plus combo handled by RunSnapshot.combo \u2014 document how combo should multiply; mixed difficulties, prefers quick cases), 'code-red' (Code Red: only cases with emergency set OR urgency 'emergency'/'urgent'; length 4; timeLimitSec override only when a case lacks its own; locked until the player has completed at least 3 cases \u2014 read your own slot or learning stats; give a friendly locked reason), 'daily' (Daily Rounds: 3 cases chosen deterministically from createRng(dayKey(services.clock.now())); same for everyone; pickNext must return them in order), 'review' (Second Opinion: prefers cases whose diagnosis is in services.learning.due(); length 4; if nothing due, choose least-mastered diagnoses; locked reason if the player has seen < 2 diagnoses). Each mode: id, player-facing title & tagline (NO sin language \u2014 see GAME_DESIGN.md), icon (emoji is fine), accent colour from the design tokens palette, order, rules, optional internal `drive` metadata. pickNext must never return a case already in run.completed/run.failed while unseen cases remain, and must return null when the pool is empty. Unit-test every mode with a fake services built via createServices() from @core and a handful of synthetic cases.\n\nC) Sandbox page src/app/sandbox/pages/modes.tsx (default export { id, title, component }) \u2014 a clean diagnostics page that lists registered modes, their lock state, and simulates a run (shows which case ids each mode would pick) using the registered cases, plus a learning-state table. Content (cases) may not exist yet when you build \u2014 handle empty registries gracefully.", "tier": "standard", "start": "build"}, {"key": "content-diagnoses", "owns": ["src/content/diagnoses/"], "brief": "Write the diagnosis encyclopedia (the in-game Codex) \u2014 pure data implementing Diagnosis (src/core/case.ts). One file per category under src/content/diagnoses/ (refractive.ts, binocular.ts, lids-conjunctiva.ts, cornea.ts, uvea-glaucoma.ts, lens.ts, retina.ts, neuro.ts, normal.ts), each `export default Diagnosis[]`. Cover EVERY canonical id in docs/GAME_DESIGN.md \u00a78 (exactly those ids \u2014 tests/content.test.ts has the list; aim for 100% coverage). Per entry: name (proper clinical name), aka (lay/alternative names), category, summary (2-4 rich sentences: what it is, who gets it, why it matters), keyFindings (3-6 exam findings that clinch it \u2014 specific with numbers/grades/signs), typicalUrgency, pearls (2-4 high-yield exam/board pearls, discriminators vs look-alikes, red flags), rarity, reference (a real EyeWiki/StatPearls/AAO URL you verified). Use docs/research/02-clinical-cases.md and 03-test-mechanics.md and verify with WebSearch (load via ToolSearch 'select:WebSearch'). Tone: clear, elegant, memorable; player-facing so never any sin words. Validate: npx vitest run tests/content.test.ts and npm run check:mod -- src/content/diagnoses. Accuracy is the #1 criterion.", "tier": "standard", "start": "build"}, {"key": "content-cases-a", "owns": ["src/content/cases/vision-binocular-neuro/"], "brief": "You write CLINICAL CASES (pure data) for Lumen. Contract: ClinicalCase in src/core/case.ts; findings built with buildFindings(age, sparsePatch) from @core (src/core/clinical-defaults.ts gives a healthy exam; override only what differs). Vocabulary for findings is the union types in src/core/clinical.ts \u2014 use them exactly. Diagnosis ids: ONLY the canonical list in docs/GAME_DESIGN.md \u00a78 (tests/content.test.ts enforces it). Test ids: src/core/tests.ts. Primary clinical source: docs/research/02-clinical-cases.md and docs/research/03-test-mechanics.md (plus docs/research/00-RESEARCH-REPORT.md) \u2014 and verify anything doubtful with WebSearch (load via ToolSearch 'select:WebSearch') against EyeWiki/AAO/AOA/StatPearls.\n\nEach case file: src/content/cases/<group>/<case-id>.ts with `export default <ClinicalCase>` (or an array). Requirements per case:\n- A memorable, diverse patient (name, age, sex, occupation, one-line personality, AvatarSpec with skin 0-5, a HairStyle value, hair/iris/outfit colours, glasses if they wear them, headwear/accessory variety; ages from children to 90s; diverse backgrounds treated respectfully). The chief complaint in the patient's own voice \u2014 vivid, human, sometimes funny, never mocking.\n- 6-10 history questions across categories with relevance key/helpful/neutral/red-herring; answers in the patient's voice. The key questions must be the ones a good clinician asks (onset, laterality, pain, photophobia, discharge, flashes/floaters, curtain, headache/jaw claudication, systemic disease, meds, contact lens wear, trauma...).\n- Findings that are internally consistent and realistic for the diagnosis (VA logMAR + pinhole behaviour, refraction in minus-cyl, keratometry, pupils incl. RAPD, motility/deviation in prism dioptres, slit-lamp signs, van Herick, cells/flare SUN grades, fluorescein pattern, IOP, CDR & disc, vessels, lesions with zones/density, fields, Amsler, colour vision, external signs that show on the avatar: redEye, tearing, ptosis, proptosis, squinting, photophobia, templeTenderness, rash). If a sign is unilateral, put it on the correct eye only.\n- essentialTests = the tests without which you cannot make the call; helpfulTests = supportive/rule-out tests. differentials: 3-5 plausible, *teachable* distractors (each must be a canonical id, not the answer).\n- urgency (routine/soon/urgent/emergency) per current guidelines; management (2-4 sentences: what you do, who you refer to, how fast); 3-5 teachingPoints (crisp pearls that discriminate from the differentials); redFlags where relevant; emergency: { timeLimitSec } (90-180) ONLY for true time-critical emergencies; sources: 1-3 URLs you actually used.\n- difficulty 1-5 spread across the set; tags (e.g. 'red-eye','sudden-vision-loss','paediatric','contact-lens').\n- Player-facing text must never contain sin words (tests/content.test.ts checks).\nValidate with: npx vitest run tests/content.test.ts  and  npm run check:mod -- src/content/cases/<group>. Both must pass for YOUR files (diagnosis entries may still be in progress by a colleague \u2014 the test tolerates a missing Diagnosis registry but not non-canonical ids). Clinical accuracy is the #1 criterion: a practising optometrist will review every number.\n\nYOUR GROUP: src/content/cases/vision-binocular-neuro/ \u2014 write 16 cases covering: myopia (teen struggling with the board), hyperopia (child or 30s with eyestrain), astigmatism, presbyopia (classic 45-year-old 'arms too short'), anisometropia, amblyopia (child), convergence-insufficiency (student reading fatigue), accommodative-esotropia (toddler eye turning in), intermittent-exotropia, cn6-palsy (diabetic with horizontal diplopia worse at distance), cn4-palsy (vertical diplopia, head tilt), cn3-palsy WITH pupil involvement (emergency: aneurysm \u2014 timer), horner-syndrome, adie-pupil, optic-neuritis (young woman, pain on eye movement, RAPD, red desaturation), papilledema (headache, obese young woman, bilateral disc oedema \u2014 urgent), pituitary-adenoma (bitemporal hemianopia), homonymous-hemianopia (stroke), giant-cell-arteritis (elderly, jaw claudication, scalp tenderness, pale swollen disc \u2014 emergency, timer), congenital-color-deficiency (male, deutan). That's 20 ideas \u2014 pick 16, prioritising teaching value, and include at least 3 emergencies with timers.", "tier": "standard", "start": "build"}, {"key": "content-cases-b", "owns": ["src/content/cases/anterior/"], "brief": "You write CLINICAL CASES (pure data) for Lumen. Contract: ClinicalCase in src/core/case.ts; findings built with buildFindings(age, sparsePatch) from @core (src/core/clinical-defaults.ts gives a healthy exam; override only what differs). Vocabulary for findings is the union types in src/core/clinical.ts \u2014 use them exactly. Diagnosis ids: ONLY the canonical list in docs/GAME_DESIGN.md \u00a78 (tests/content.test.ts enforces it). Test ids: src/core/tests.ts. Primary clinical source: docs/research/02-clinical-cases.md and docs/research/03-test-mechanics.md (plus docs/research/00-RESEARCH-REPORT.md) \u2014 and verify anything doubtful with WebSearch (load via ToolSearch 'select:WebSearch') against EyeWiki/AAO/AOA/StatPearls.\n\nEach case file: src/content/cases/<group>/<case-id>.ts with `export default <ClinicalCase>` (or an array). Requirements per case:\n- A memorable, diverse patient (name, age, sex, occupation, one-line personality, AvatarSpec with skin 0-5, a HairStyle value, hair/iris/outfit colours, glasses if they wear them, headwear/accessory variety; ages from children to 90s; diverse backgrounds treated respectfully). The chief complaint in the patient's own voice \u2014 vivid, human, sometimes funny, never mocking.\n- 6-10 history questions across categories with relevance key/helpful/neutral/red-herring; answers in the patient's voice. The key questions must be the ones a good clinician asks (onset, laterality, pain, photophobia, discharge, flashes/floaters, curtain, headache/jaw claudication, systemic disease, meds, contact lens wear, trauma...).\n- Findings that are internally consistent and realistic for the diagnosis (VA logMAR + pinhole behaviour, refraction in minus-cyl, keratometry, pupils incl. RAPD, motility/deviation in prism dioptres, slit-lamp signs, van Herick, cells/flare SUN grades, fluorescein pattern, IOP, CDR & disc, vessels, lesions with zones/density, fields, Amsler, colour vision, external signs that show on the avatar: redEye, tearing, ptosis, proptosis, squinting, photophobia, templeTenderness, rash). If a sign is unilateral, put it on the correct eye only.\n- essentialTests = the tests without which you cannot make the call; helpfulTests = supportive/rule-out tests. differentials: 3-5 plausible, *teachable* distractors (each must be a canonical id, not the answer).\n- urgency (routine/soon/urgent/emergency) per current guidelines; management (2-4 sentences: what you do, who you refer to, how fast); 3-5 teachingPoints (crisp pearls that discriminate from the differentials); redFlags where relevant; emergency: { timeLimitSec } (90-180) ONLY for true time-critical emergencies; sources: 1-3 URLs you actually used.\n- difficulty 1-5 spread across the set; tags (e.g. 'red-eye','sudden-vision-loss','paediatric','contact-lens').\n- Player-facing text must never contain sin words (tests/content.test.ts checks).\nValidate with: npx vitest run tests/content.test.ts  and  npm run check:mod -- src/content/cases/<group>. Both must pass for YOUR files (diagnosis entries may still be in progress by a colleague \u2014 the test tolerates a missing Diagnosis registry but not non-canonical ids). Clinical accuracy is the #1 criterion: a practising optometrist will review every number.\n\nYOUR GROUP: src/content/cases/anterior/ \u2014 write 16 cases covering: dry-eye (screen worker, low TBUT, inferior/interpalpebral staining), blepharitis/meibomian dysfunction, chalazion, hordeolum, bacterial-conjunctivitis (mucopurulent, lids stuck), viral-conjunctivitis (follicles, watery, preauricular node, recent cold), allergic-conjunctivitis (itch, papillae, stringy discharge, chemosis), subconjunctival-hemorrhage (asymptomatic red patch, check BP/anticoagulants), pinguecula, pterygium, episcleritis, corneal-abrasion (linear staining, fingernail/baby), corneal-foreign-body (grinder, rust ring), hsv-keratitis (dendrite, terminal bulbs, reduced sensation), microbial-keratitis (contact lens wearer slept in lenses \u2014 urgent, round ulcer + infiltrate + AC reaction), keratoconus (young adult, scissors reflex, irregular mires, Vogt striae, Fleischer ring), herpes-zoster-ophthalmicus (dermatomal rash, Hutchinson sign), anterior-uveitis (ciliary flush, cells/flare, KPs, photophobia, small pupil, HLA-B27/back pain), acute-angle-closure (emergency with timer: halos, nausea, IOP ~50, mid-dilated fixed pupil, corneal oedema, shallow AC, van Herick 1), cataract (glare, nuclear sclerosis, myopic shift, pinhole little help), poag (asymptomatic, CDR 0.7-0.8, inferior rim thinning, arcuate defect, IOP 26), ocular-hypertension, normal-tension-glaucoma. Pick the 16 with best teaching value; include at least 2 emergencies/urgent with timers where appropriate (angle closure, microbial keratitis).", "tier": "standard", "start": "build"}, {"key": "content-cases-c", "owns": ["src/content/cases/retina-emergency/"], "brief": "You write CLINICAL CASES (pure data) for Lumen. Contract: ClinicalCase in src/core/case.ts; findings built with buildFindings(age, sparsePatch) from @core (src/core/clinical-defaults.ts gives a healthy exam; override only what differs). Vocabulary for findings is the union types in src/core/clinical.ts \u2014 use them exactly. Diagnosis ids: ONLY the canonical list in docs/GAME_DESIGN.md \u00a78 (tests/content.test.ts enforces it). Test ids: src/core/tests.ts. Primary clinical source: docs/research/02-clinical-cases.md and docs/research/03-test-mechanics.md (plus docs/research/00-RESEARCH-REPORT.md) \u2014 and verify anything doubtful with WebSearch (load via ToolSearch 'select:WebSearch') against EyeWiki/AAO/AOA/StatPearls.\n\nEach case file: src/content/cases/<group>/<case-id>.ts with `export default <ClinicalCase>` (or an array). Requirements per case:\n- A memorable, diverse patient (name, age, sex, occupation, one-line personality, AvatarSpec with skin 0-5, a HairStyle value, hair/iris/outfit colours, glasses if they wear them, headwear/accessory variety; ages from children to 90s; diverse backgrounds treated respectfully). The chief complaint in the patient's own voice \u2014 vivid, human, sometimes funny, never mocking.\n- 6-10 history questions across categories with relevance key/helpful/neutral/red-herring; answers in the patient's voice. The key questions must be the ones a good clinician asks (onset, laterality, pain, photophobia, discharge, flashes/floaters, curtain, headache/jaw claudication, systemic disease, meds, contact lens wear, trauma...).\n- Findings that are internally consistent and realistic for the diagnosis (VA logMAR + pinhole behaviour, refraction in minus-cyl, keratometry, pupils incl. RAPD, motility/deviation in prism dioptres, slit-lamp signs, van Herick, cells/flare SUN grades, fluorescein pattern, IOP, CDR & disc, vessels, lesions with zones/density, fields, Amsler, colour vision, external signs that show on the avatar: redEye, tearing, ptosis, proptosis, squinting, photophobia, templeTenderness, rash). If a sign is unilateral, put it on the correct eye only.\n- essentialTests = the tests without which you cannot make the call; helpfulTests = supportive/rule-out tests. differentials: 3-5 plausible, *teachable* distractors (each must be a canonical id, not the answer).\n- urgency (routine/soon/urgent/emergency) per current guidelines; management (2-4 sentences: what you do, who you refer to, how fast); 3-5 teachingPoints (crisp pearls that discriminate from the differentials); redFlags where relevant; emergency: { timeLimitSec } (90-180) ONLY for true time-critical emergencies; sources: 1-3 URLs you actually used.\n- difficulty 1-5 spread across the set; tags (e.g. 'red-eye','sudden-vision-loss','paediatric','contact-lens').\n- Player-facing text must never contain sin words (tests/content.test.ts checks).\nValidate with: npx vitest run tests/content.test.ts  and  npm run check:mod -- src/content/cases/<group>. Both must pass for YOUR files (diagnosis entries may still be in progress by a colleague \u2014 the test tolerates a missing Diagnosis registry but not non-canonical ids). Clinical accuracy is the #1 criterion: a practising optometrist will review every number.\n\nYOUR GROUP: src/content/cases/retina-emergency/ \u2014 write 14 cases covering: npdr (moderate, dot-blot + MAs + hard exudates), pdr (NVD/NVE, vitreous haemorrhage risk \u2014 urgent), diabetic-macular-edema, hypertensive-retinopathy (AV nicking, flame haemorrhages, cotton-wool spots; malignant variant with disc oedema = emergency), dry-amd (drusen, GA, slow decline), wet-amd (sudden metamorphopsia, Amsler distortion, subretinal haemorrhage \u2014 urgent), retinal-detachment (curtain, flashes/floaters, macula-on = emergency with timer), pvd (flashes/floaters, Weiss ring, no tear \u2014 still needs dilated exam same/next day), retinal-tear (horseshoe tear, Shafer sign pigment in vitreous), crao (sudden painless loss, cherry-red spot, whitening, RAPD \u2014 emergency stroke pathway, timer), crvo (blood-and-thunder, dilated tortuous veins), brvo (sectoral haemorrhages at AV crossing), central-serous (young stressed male, steroid use, blurred/dim central vision, hyperopic shift), healthy-eyes (a worried patient whose exam is completely normal \u2014 teaches restraint & reassurance; differentials should be tempting look-alikes). Include at least 3 emergencies with timers (macula-on RD, CRAO, + one more).", "tier": "standard", "start": "build"}, {"key": "mg-visual-acuity", "owns": ["src/minigames/visual-acuity/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: visual-acuity + pinhole (export an array of TWO modules: ids 'visual-acuity' and 'pinhole') \u2014 folder src/minigames/visual-acuity/ ===\nA gorgeous back-lit projector chart (Snellen letters in proper Sloan optotype proportions, plus a LogMAR/ETDRS mode toggle; tumbling-E or LEA symbols for young children). The chart is blurred realistically according to the eye's uncorrected refractive error (blur from spherical equivalent and cylinder \u2014 astigmatism blurs directionally) and pathology (BCVA limit). Player occludes one eye (animated occluder on a mini patient avatar), points to lines, and the patient 'reads' via speech bubbles \u2014 reading correctly above threshold and making characteristic errors near it; the player must find the smallest line read (\u2265 more than half the letters) for OD, OS, (OU optional). Accuracy = how close the recorded acuity is to truth & technique (occluding correctly, one eye at a time). Record logMAR and Snellen (respect metric VA setting is not available in ctx \u2014 show 20/x with 6/x secondary). PINHOLE module: the occluder flips to a pinhole; refractive blur clears and pathology does not \u2014 player judges 'improves' vs 'no improvement'. report(): VA sc OD/OS, PH if relevant; flag abnormal when worse than 20/40 (critical at \u2264 20/200).", "tier": "standard", "start": "review"}, {"key": "mg-phoropter", "owns": ["src/minigames/phoropter/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: phoropter \u2014 folder src/minigames/phoropter/ ===\nSubjective refraction on a stunning brass-and-glass phoropter (front view with the two lens apertures, dials for sphere, cylinder, axis, JCC flip, duochrome toggle). The patient view chart blurs per the residual refractive error: residual = true Rx \u2212 dialled lens (vector math for cylinder; use power vectors M, J0, J45). Classic flow: start from a retinoscopy/autorefraction estimate (perturbed by difficulty), fog, sphere bracketing with 'which is better, one or two?' prompts the PATIENT answers (truthfully with occasional uncertainty near endpoint), JCC axis then power refinement, maximum plus to best VA, duochrome check, optional binocular balance. Patient answers come in speech bubbles. Accuracy from final Rx error (spherical equivalent and cylinder vector distance; quarter-dioptre precision) and number of steps. report(): Rx OD/OS in minus-cyl formatted with formatRx, BCVA, Add if presbyopic; flag abnormal when significantly ametropic? (flag 'normal' for any correctable refraction unless BCVA reduced).", "tier": "heavy", "start": "review"}, {"key": "mg-retinoscopy", "owns": ["src/minigames/retinoscopy/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: retinoscopy \u2014 folder src/minigames/retinoscopy/ ===\nStreak retinoscopy: the player sweeps a streak (mouse/touch drag or arrow keys) across a big glowing pupil with a red-orange reflex. The reflex moves WITH (hyperopic/under-plussed relative to working distance) or AGAINST (myopic beyond far point), speed and brightness and width vary with how far from neutral; at neutrality the pupil fills/flashes. Player rotates the streak to find principal meridians (astigmatism: the reflex is broken/misaligned off-axis; band aligns at the correct axis), adds lenses from a lens rack / dial to neutralise each meridian, and remembers working distance (e.g. 67cm \u2192 subtract +1.50 D). Reflex quality per findings.retinoscopyReflex: 'scissors' (keratoconus), 'dull' (cataract/media opacity), 'absent'. Accuracy from final net Rx vs truth. report(): 'Ret' net result per eye + reflex quality flags.", "tier": "heavy", "start": "review"}, {"key": "mg-keratometry", "owns": ["src/minigames/keratometry/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: keratometry \u2014 folder src/minigames/keratometry/ ===\nKeratometer (one-position Bausch & Lomb style): view through the eyepiece shows the three mires on the cornea; the player focuses (doubling \u2192 single), aligns horizontal and vertical plus/minus signs by turning two measurement drums, and rotates the instrument to the principal meridian. Reading K1/K2 and axis; irregular/distorted mires for keratoconus. Show the corneal cylinder = K difference. Accuracy from reading error. report(): K1/K2 @ axis per eye, corneal astigmatism, mires quality; flag abnormal for steep K > 47 D or irregular mires.", "tier": "standard", "start": "continue"}, {"key": "mg-pupils", "owns": ["src/minigames/pupils/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: pupils \u2014 folder src/minigames/pupils/ ===\nPupil exam in a dimmed room: big close-up of BOTH eyes (use @render eye renderer, lighting 'dim'/'penlight') with a penlight the player controls (drag, or keys to swing). Pupils constrict/dilate with realistic latency and dynamics; consensual response; swinging flashlight test where an RAPD eye paradoxically dilates when the light swings onto it (grade by findings.pupils.rapdGrade); anisocoria that differs in light vs dark (Horner: small pupil worse in dark + mild ptosis; CN3/Adie: large pupil worse in light; Adie tonic slow redilation; light-near dissociation via a near-target button). Measure pupil sizes with a pupil gauge overlay (half-circles 2-9mm). Player tasks: measure sizes in light and dark, perform swinging light \u2265 3 swings, test near. Accuracy: technique (dwell time 2-3s per eye, enough swings) + measurement accuracy. report(): sizes light/dark, reactivity, RAPD (critical), near response, anisocoria.", "tier": "standard", "start": "review"}, {"key": "mg-cover-test", "owns": ["src/minigames/cover-test/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: cover-test \u2014 folder src/minigames/cover-test/ ===\nCover/uncover and alternate cover test on a close-up of the patient's eyes (@render eye renderer, gaze offsets) with a translucent black occluder paddle the player moves (drag/keys) between eyes, distance vs near target toggle. Simulate exactly: tropia \u2014 covering the fixating eye makes the deviated eye take up fixation (refixation movement in the correct direction: eso \u2192 moves out; exo \u2192 moves in; hyper \u2192 down); phoria \u2014 no movement on cover; on uncover the covered eye recovers; alternate cover reveals total deviation. Then a prism bar the player slides in (base-out for eso, base-in for exo) until neutralised to measure prism dioptres. Accuracy from correct classification (ortho/phoria/tropia/intermittent, eso/exo/hyper, which eye) + prism measurement. report(): distance & near deviation e.g. '12\u0394 constant L esotropia' with flags.", "tier": "standard", "start": "review"}, {"key": "mg-motility", "owns": ["src/minigames/motility/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: motility + convergence (export an array of TWO modules: 'motility' and 'convergence') \u2014 folder src/minigames/motility/ ===\nMOTILITY: broad H-pattern \u2014 the player moves a glowing fixation wand (drag/keys) through the 9 positions of gaze while the patient's eyes (@render eye renderer or high-quality SVG of both eyes on the avatar face) follow; versions per findings.motility.versions show underactions/overactions (e.g. CN6: abduction deficit; CN4: affected eye overelevates in adduction; CN3: eye down-and-out with ptosis); patient reports diplopia in certain gazes and pain on movement (optic neuritis). Player marks the motility diagram (H chart with +/- grades) \u2014 accuracy from correct grading. CONVERGENCE: an RAF accommodative target moves towards the nose along a ruler; eyes converge until the break point (findings.motility.npcCm) when one eye drifts out and the patient says 'double!'; player stops the target at break and recovery; also amplitude of accommodation push-up (blur point vs expected for age). report(): versions summary, NPC break/recovery cm (abnormal > 10cm), amplitude.", "tier": "standard", "start": "review"}, {"key": "mg-color-vision", "owns": ["src/minigames/color-vision/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: color-vision \u2014 folder src/minigames/color-vision/ ===\nPseudo-isochromatic plates generated procedurally: circle of packed random-size dots (proper circle packing), numerals/paths drawn using colours along protan/deutan/tritan confusion lines so a normal observer sees one number and a colour-deficient patient sees another or none (vanishing, transformation and hidden-digit plate types; a demonstration plate everyone reads). The player shows plates; the patient answers per findings.colorVision (type, severity, monocular acquired defects in optic neuritis with red desaturation \u2014 include a red-cap desaturation comparison mini-step). The player must classify: normal / protan / deutan / tritan / acquired, and which eye. Make plates look premium (soft lighting, paper texture). Do NOT call it 'Ishihara' in UI (use 'Colour plates'). report(): plates correct x/y per eye, interpretation.", "tier": "standard", "start": "review"}, {"key": "mg-amsler", "owns": ["src/minigames/amsler/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: amsler \u2014 folder src/minigames/amsler/ ===\nAmsler grid: the patient fixates the central dot and DRAWS what they see \u2014 reproduce: the 10cm 20x20 grid on a dark card; the player 'asks' the patient and sees the patient's perception overlay (wavy/bent lines = metamorphopsia; missing/grey area = scotoma) per findings.amsler (center, radius) for each eye; player traces/marks the abnormal region on the grid (draw with pointer). Accuracy = overlap (IoU) between marked and true region + correct classification. Also a practice mode where the player is shown distortions. Render with a beautiful lens-warp shader effect in canvas. report(): Amsler OD/OS normal / metamorphopsia / scotoma with location (superotemporal etc.), flag abnormal (critical for new metamorphopsia in an AMD-age patient? flag abnormal).", "tier": "standard", "start": "review"}, {"key": "mg-visual-fields", "owns": ["src/minigames/visual-fields/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: visual-fields \u2014 folder src/minigames/visual-fields/ ===\nVisual field test \u2014 automated perimetry-style: dark bowl, fixation light, the player presents stimuli by clicking locations on the field (or runs a fast 'auto-threshold' sweep), the patient clicks a buzzer when seen (patient responses follow findings.fields defect maps per eye with slight noise; blind spot temporally at 15\u00b0). As points are tested, a greyscale plot builds up (like a printout). Then the player classifies the defect pattern from options (arcuate, nasal step, central/cecocentral scotoma, altitudinal, bitemporal hemianopia, homonymous hemianopia L/R, quadrantanopia, constriction, enlarged blind spot, full). Implement a geometric model for every FieldDefect value with correct laterality (left/right eye, temporal/nasal). Also produce a combined binocular interpretation (bitemporal = chiasm; homonymous = retrochiasmal). Accuracy = coverage efficiency + correct classification. report(): field per eye described + localisation hint.", "tier": "standard", "start": "continue"}, {"key": "mg-slit-lamp", "owns": ["src/minigames/slit-lamp/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: slit-lamp + fluorescein (export an array of TWO modules: 'slit-lamp' and 'fluorescein') \u2014 folder src/minigames/slit-lamp/ ===\nSLIT LAMP: the signature mini-game. A cinematic, realistic slit-lamp view through the oculars: joystick (drag) to move across lids \u2192 conjunctiva \u2192 cornea \u2192 AC \u2192 iris \u2192 lens; controls for beam width (diffuse / broad / narrow optical section / conical beam), beam angle, magnification (10x/16x/25x), illumination filter (white, cobalt blue, red-free). Uses @render drawEye + drawSlitSection. Findings appear only when correctly examined (e.g. AC cells only visible with a short narrow conical beam at high magnification in the dark; van Herick requires a narrow beam at 60\u00b0 at the temporal limbus; KPs on the endothelium; lens opacities in retro-illumination). The player 'tags' findings by clicking on them \u2192 a radial menu of sign names (from the clinical vocabulary) to identify; correct tags score. FLUORESCEIN: instil a drop (satisfying animation), wait/blink, switch to cobalt blue + yellow barrier filter: staining patterns appear exactly per findings.anterior.fluorescein; tear break-up time counter (dark spots forming in the green tear film) the player times with a stopwatch; Seidel test for perforation not required. report(): structured anterior segment summary per eye (lids, conj, cornea, AC depth/van Herick, cells/flare grade, iris, lens grade), fluorescein pattern + TBUT; flags.", "tier": "heavy", "start": "review"}, {"key": "mg-tonometry", "owns": ["src/minigames/tonometry/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: tonometry \u2014 folder src/minigames/tonometry/ ===\nGoldmann applanation tonometry: in cobalt light the player sees the two fluorescein semicircle mires through the biprism; must first centre them (joystick), then turn the measuring drum (dial in mmHg \u00d710 gram-units) until the inner edges of the semicircles just touch. Mires pulse with the ocular pulse; mire thickness changes with fluorescein amount (too thick \u2192 overestimate). Correct endpoint = true IOP. Also offer iCare rebound as an alternative quick mode (6 shots, averaged). Accuracy from endpoint error (\u00b11 mmHg perfect) + correct alignment. Anaesthetic drop + fluorescein animation first. report(): IOP OD/OS mmHg, method, time; flag abnormal > 21, critical \u2265 35 or asymmetry > 6? (be clinically sensible).", "tier": "standard", "start": "review"}, {"key": "mg-ophthalmoscopy", "owns": ["src/minigames/ophthalmoscopy/"], "brief": "You build ONE clinical-test MINI-GAME plugin for Lumen. Contract: MiniGameModule in src/core/minigame.ts \u2014 read it carefully. Your folder's index.ts must `export default` the module (or an array of modules when your folder implements two TestIds). The exam room opens your game inside a large modal stage (assume ~960x620 desktop, full-screen on phones, \u2265 375px wide) and passes a MiniGameContext: patient, the patient's true PatientFindings, mode ('case' | 'practice'), difficulty 0..1, rng, audio, fx, reducedMotion.\n\nDesign rules for every mini-game:\n- It must feel like operating a beautiful, precise optical INSTRUMENT: tactile dials/knobs (drag + mouse wheel + arrow keys), lens clicks (ctx.audio.play('lens-click'|'dial'|...)), smooth eased animation, glows, depth. Reuse @render (eye renderer: drawEye/EyeCanvas/eyeStateFromFindings/drawSlitSection/paintIrisArt; fundus: paintFundus/FundusView; avatars: PatientAvatar; FX) and @ui-kit components (Button, Icon, GlassPanel, Meter, etc.) \u2014 read src/render/**/index.ts and src/ui-kit/index.ts for their real APIs first.\n- Layout: a slim header strip with a one-line instruction + OD/OS eye selector where relevant; the instrument stage; a footer with progress and a gold 'Record findings' button. A first-time micro-tutorial overlay (2-3 steps, skippable).\n- The behaviour must be OPTICALLY/CLINICALLY TRUE to the findings (e.g. blur scales with uncorrected refractive error, a +lens fogs a myope, RAPD shows paradoxical dilation, against-motion for myopia beyond the working distance, mires overlap at the true IOP...). Use docs/research/03-test-mechanics.md for procedure and scales.\n- In 'case' mode the chart must be clinically correct: call done() with findings = report(ctx.findings, ctx.patient) (true values, flagged normal/abnormal/critical vs norms), and accuracy 0..1 reflecting how well the player performed the technique (precision, completeness, time); set perfect when flawless. In 'practice' mode end with a recognition challenge (e.g. 'What is the IOP?', 'Which eye has the RAPD?', 'With or against?') and score it; show the answer with a short teaching explanation.\n- report() is pure and well-unit-tested: it turns findings into crisp chart lines (e.g. label 'IOP', value '48 mmHg', eye 'OD', flag 'critical').\n- practice(rng, difficulty) generates varied, clinically coherent scenarios using buildFindings + generateAvatar (from @render) \u2014 mix normal and pathological, harder with difficulty.\n- Call done() exactly once; the returned cleanup must remove every listener, RAF, timer, and DOM node. Keyboard accessible, touch-friendly, honours ctx.reducedMotion. No console errors.\n- View & screenshot it at ?sandbox=minigame/<id> (add &case=<caseId> to use a real case if any exist; the harness shows the result JSON after done()). Drive interactions with a throwaway Playwright script (require('playwright')) to verify the whole flow reaches done().\n- Player-facing text: never any sin words.\n\n=== YOUR MINI-GAME: ophthalmoscopy \u2014 folder src/minigames/ophthalmoscopy/ ===\nDirect/indirect ophthalmoscopy spot-the-finding: use @render paintFundus/FundusView with a movable light circle (direct) or wide view (indirect/BIO with a 20D lens \u2014 inverted image; consider a toggle). The player explores the fundus (drag/keys), and clicks findings to tag them via a radial menu: disc (estimate CDR with a slider 0.1-0.9 and rim/ISNT, pallor, swelling), vessels (AV ratio, nicking, copper wiring, venous dilation), macula, and each lesion type present (using FundusMap hit regions). False tags cost points. Red reflex check first (findings.redReflex: dull for cataract, absent for vitreous haemorrhage, leukocoria). Red-free filter toggle to make haemorrhages/NFL defects pop. Accuracy = recall/precision of tags + CDR estimate error. report(): disc (CDR, colour, margins), vessels, macula, periphery/lesions summary, detachment, vitreous; flags.", "tier": "heavy", "start": "review"}, {"key": "sys-ranks", "owns": ["src/systems/ranks/", "src/app/sandbox/pages/sys-ranks.tsx"], "brief": "You build ONE ENGAGEMENT SYSTEM plugin for Lumen. Contract: SystemModule in src/core/systems.ts (id, player-facing name, internal `drive`, color, install(services) \u2192 uninstall). Read docs/ENGAGEMENT_DESIGN.md (internal psychology lens) and docs/research/04-sins-engagement.md for mechanics + ethical guardrails, and docs/GAME_DESIGN.md \u00a77 for your system's player-facing name and scope.\nHow systems plug in (never import other systems/scenes \u2014 boundaries are enforced):\n- Persist state with services.save.slot('sys:<id>', initial, { version }).\n- Listen to bus events (src/core/events.ts): case:started, history:asked, test:completed, diagnosis:submitted, case:completed (has the full ScoreBreakdown), case:failed, mode:started/ended, practice:completed, currency:grant/currency:changed, xp:grant/rank:changed, patient:arriving, app:ready, scene:changed.\n- Announce rewards with bus.emit('reward:granted', {source:'<id>', label, value, icon, color, rarity}) \u2014 the results screen shows them; use toast / achievement:unlocked events for moments; juice with services.fx and services.audio.\n- Contribute UI by registering in install(): HudWidgets (services.registries.hud.register({ id, slot, order, system:'<id>', component })) for slots topbar-left | topbar-right | hub-banner | hub-sidebar | exam-overlay | results-extra | profile; a HubEntry tile (services.registries.hub.register(...)) and, if your system has a page, a SceneModule (services.registries.scenes.register(...)) with a full-screen scene using @ui-kit Screen/Backdrop. Components are Preact; read state with useSignal from @ui-kit.\n- install() must be idempotent-safe and the returned uninstall must unsubscribe everything. The game must remain fully playable if your folder is deleted.\n- Rewards must scale with LEARNING quality (correctness, efficiency, mastery), never with mere time spent; follow the ethical guardrails (no real money, no punitive loss, streak repair, natural stopping points).\n- Polish: this is where players fall in love \u2014 make every widget and scene gorgeous (glass, glow, motion, count-ups, particles, sound), responsive (375px), accessible.\n- PLAYER-FACING TEXT NEVER CONTAINS SIN WORDS. Use the clinic-themed names.\n- Test logic with vitest using createServices() from @core (no DOM needed for most logic). Preview: create a sandbox page src/app/sandbox/pages/sys-<id>.tsx (default export { id, title, component }) that installs your system into props.services (`yourSystem.install(props.services)` via the folder's default export \u2014 the sandbox page is in src/app so it may import your folder) and fires synthetic events (e.g. fake case:completed with a ScoreBreakdown) with buttons, rendering your HUD widgets and scene \u2014 so reviewers can screenshot it at ?sandbox=page/sys-<id>. Scenes from other teams may still be under construction.\n\n=== YOUR SYSTEM: id 'ranks', player-facing name 'Career', internal drive 'pride' (never shown) \u2014 folder src/systems/ranks/ ===\nXP & rank ladder (Student \u2192 Intern \u2192 Resident \u2192 Associate \u2192 Senior \u2192 Clinic Director \u2192 Living Legend, with sub-levels and a smooth XP curve), XP from case:completed (scaled by score/grade, bonus for perfect & first-time diagnoses), xp:grant events from others; emit rank:changed with a spectacular rank-up moment (fx burst + 'levelup' + toast + achievement). Mastery stars (0-3) per diagnosis from services.learning.mastery() and grades. A trophy wall of 30+ achievements (first diagnosis, first S grade, 5 perfect cases, every test used, all emergencies triaged, 'Eagle eye' spot every fundus lesion, categories mastered, etc. \u2014 clinically themed names), achievement:unlocked events. HUD: topbar-left rank badge + XP ring; profile slot section; results-extra panel with XP gained animation and next-rank progress. Scene 'career': gorgeous career page (rank crest, XP bar, mastery constellation map of all diagnoses by category \u2014 stars light up as mastered, trophy wall with locked silhouettes). HubEntry to 'career'.", "tier": "standard", "start": "review"}, {"key": "sys-economy", "owns": ["src/systems/economy/", "src/app/sandbox/pages/sys-economy.tsx"], "brief": "You build ONE ENGAGEMENT SYSTEM plugin for Lumen. Contract: SystemModule in src/core/systems.ts (id, player-facing name, internal `drive`, color, install(services) \u2192 uninstall). Read docs/ENGAGEMENT_DESIGN.md (internal psychology lens) and docs/research/04-sins-engagement.md for mechanics + ethical guardrails, and docs/GAME_DESIGN.md \u00a77 for your system's player-facing name and scope.\nHow systems plug in (never import other systems/scenes \u2014 boundaries are enforced):\n- Persist state with services.save.slot('sys:<id>', initial, { version }).\n- Listen to bus events (src/core/events.ts): case:started, history:asked, test:completed, diagnosis:submitted, case:completed (has the full ScoreBreakdown), case:failed, mode:started/ended, practice:completed, currency:grant/currency:changed, xp:grant/rank:changed, patient:arriving, app:ready, scene:changed.\n- Announce rewards with bus.emit('reward:granted', {source:'<id>', label, value, icon, color, rarity}) \u2014 the results screen shows them; use toast / achievement:unlocked events for moments; juice with services.fx and services.audio.\n- Contribute UI by registering in install(): HudWidgets (services.registries.hud.register({ id, slot, order, system:'<id>', component })) for slots topbar-left | topbar-right | hub-banner | hub-sidebar | exam-overlay | results-extra | profile; a HubEntry tile (services.registries.hub.register(...)) and, if your system has a page, a SceneModule (services.registries.scenes.register(...)) with a full-screen scene using @ui-kit Screen/Backdrop. Components are Preact; read state with useSignal from @ui-kit.\n- install() must be idempotent-safe and the returned uninstall must unsubscribe everything. The game must remain fully playable if your folder is deleted.\n- Rewards must scale with LEARNING quality (correctness, efficiency, mastery), never with mere time spent; follow the ethical guardrails (no real money, no punitive loss, streak repair, natural stopping points).\n- Polish: this is where players fall in love \u2014 make every widget and scene gorgeous (glass, glow, motion, count-ups, particles, sound), responsive (375px), accessible.\n- PLAYER-FACING TEXT NEVER CONTAINS SIN WORDS. Use the clinic-themed names.\n- Test logic with vitest using createServices() from @core (no DOM needed for most logic). Preview: create a sandbox page src/app/sandbox/pages/sys-<id>.tsx (default export { id, title, component }) that installs your system into props.services (`yourSystem.install(props.services)` via the folder's default export \u2014 the sandbox page is in src/app so it may import your folder) and fires synthetic events (e.g. fake case:completed with a ScoreBreakdown) with buttons, rendering your HUD widgets and scene \u2014 so reviewers can screenshot it at ?sandbox=page/sys-<id>. Scenes from other teams may still be under construction.\n\n=== YOUR SYSTEM: id 'economy', player-facing name 'Boutique & coins', internal drive 'greed' (never shown) \u2014 folder src/systems/economy/ ===\nCoins (\u2726 'lumens'): pay per case:completed scaled by grade/total, combo-friendly; handle currency:grant from others; emit currency:changed. Surprise SUPPLY CRATES (variable-ratio rewards): earn a crate on S grades / streak milestones / rank-ups; opening is a theatrical animation (crate shakes, light leaks, burst) revealing coins, hint tokens, or cosmetic items with rarity tiers (common/rare/epic/legendary) \u2014 deterministic RNG via services.rng.fork. Boutique scene 'boutique': a luxurious shop (velvet, brass, glass cases) selling cosmetics only for coins: clinic colour themes (apply by setting a data-theme attribute / CSS variables on document.documentElement \u2014 ship 4-6 themes that recolour accents tastefully), player eyewear frames for the profile, nameplate styles; owned/equipped states. No real money anywhere. HUD: topbar-left coin counter with count-up and coin-burst on gain; results-extra coins earned + crate reveal. HubEntry to 'boutique' with badge when crates are unopened.", "tier": "standard", "start": "review"}, {"key": "sys-rivals", "owns": ["src/systems/rivals/", "src/app/sandbox/pages/sys-rivals.tsx"], "brief": "You build ONE ENGAGEMENT SYSTEM plugin for Lumen. Contract: SystemModule in src/core/systems.ts (id, player-facing name, internal `drive`, color, install(services) \u2192 uninstall). Read docs/ENGAGEMENT_DESIGN.md (internal psychology lens) and docs/research/04-sins-engagement.md for mechanics + ethical guardrails, and docs/GAME_DESIGN.md \u00a77 for your system's player-facing name and scope.\nHow systems plug in (never import other systems/scenes \u2014 boundaries are enforced):\n- Persist state with services.save.slot('sys:<id>', initial, { version }).\n- Listen to bus events (src/core/events.ts): case:started, history:asked, test:completed, diagnosis:submitted, case:completed (has the full ScoreBreakdown), case:failed, mode:started/ended, practice:completed, currency:grant/currency:changed, xp:grant/rank:changed, patient:arriving, app:ready, scene:changed.\n- Announce rewards with bus.emit('reward:granted', {source:'<id>', label, value, icon, color, rarity}) \u2014 the results screen shows them; use toast / achievement:unlocked events for moments; juice with services.fx and services.audio.\n- Contribute UI by registering in install(): HudWidgets (services.registries.hud.register({ id, slot, order, system:'<id>', component })) for slots topbar-left | topbar-right | hub-banner | hub-sidebar | exam-overlay | results-extra | profile; a HubEntry tile (services.registries.hub.register(...)) and, if your system has a page, a SceneModule (services.registries.scenes.register(...)) with a full-screen scene using @ui-kit Screen/Backdrop. Components are Preact; read state with useSignal from @ui-kit.\n- install() must be idempotent-safe and the returned uninstall must unsubscribe everything. The game must remain fully playable if your folder is deleted.\n- Rewards must scale with LEARNING quality (correctness, efficiency, mastery), never with mere time spent; follow the ethical guardrails (no real money, no punitive loss, streak repair, natural stopping points).\n- Polish: this is where players fall in love \u2014 make every widget and scene gorgeous (glass, glow, motion, count-ups, particles, sound), responsive (375px), accessible.\n- PLAYER-FACING TEXT NEVER CONTAINS SIN WORDS. Use the clinic-themed names.\n- Test logic with vitest using createServices() from @core (no DOM needed for most logic). Preview: create a sandbox page src/app/sandbox/pages/sys-<id>.tsx (default export { id, title, component }) that installs your system into props.services (`yourSystem.install(props.services)` via the folder's default export \u2014 the sandbox page is in src/app so it may import your folder) and fires synthetic events (e.g. fake case:completed with a ScoreBreakdown) with buttons, rendering your HUD widgets and scene \u2014 so reviewers can screenshot it at ?sandbox=page/sys-<id>. Scenes from other teams may still be under construction.\n\n=== YOUR SYSTEM: id 'rivals', player-facing name 'Rivals', internal drive 'envy' (never shown) \u2014 folder src/systems/rivals/ ===\n3-5 AI colleagues with distinct personalities and procedurally generated avatars (use @render generateAvatar/AvatarBust with fixed seeds) \u2014 e.g. Dr. Vex (brilliant, smug), Dr. Amara Okafor (meticulous), Dr. Kenji Mori (fast), Dr. Luc\u00eda Reyes (kind mentor) \u2014 each with a deterministic simulated performance per case (score, time, grade, sometimes making a classic mistake that teaches something: 'skipped tonometry, missed the angle closure'). Weekly league board (resets weekly by dayKey/week number) mixing rival points that grow over the week with the player's points from case:completed; overtake moments ('You passed Dr. Vex!' toast + fx) and being overtaken nudges (gentle). HUD: topbar-right mini standing (#2 \u2191); results-extra 'How your colleagues did on this patient' comparison with their quips; hub-sidebar card. Scene 'rivals': a gorgeous league table with portraits, sparkline of the week, rival profile cards and their 'signature' strengths. HubEntry to 'rivals'. Keep it motivating, never humiliating.", "tier": "standard", "start": "review"}, {"key": "sys-streaks", "owns": ["src/systems/streaks/", "src/app/sandbox/pages/sys-streaks.tsx"], "brief": "You build ONE ENGAGEMENT SYSTEM plugin for Lumen. Contract: SystemModule in src/core/systems.ts (id, player-facing name, internal `drive`, color, install(services) \u2192 uninstall). Read docs/ENGAGEMENT_DESIGN.md (internal psychology lens) and docs/research/04-sins-engagement.md for mechanics + ethical guardrails, and docs/GAME_DESIGN.md \u00a77 for your system's player-facing name and scope.\nHow systems plug in (never import other systems/scenes \u2014 boundaries are enforced):\n- Persist state with services.save.slot('sys:<id>', initial, { version }).\n- Listen to bus events (src/core/events.ts): case:started, history:asked, test:completed, diagnosis:submitted, case:completed (has the full ScoreBreakdown), case:failed, mode:started/ended, practice:completed, currency:grant/currency:changed, xp:grant/rank:changed, patient:arriving, app:ready, scene:changed.\n- Announce rewards with bus.emit('reward:granted', {source:'<id>', label, value, icon, color, rarity}) \u2014 the results screen shows them; use toast / achievement:unlocked events for moments; juice with services.fx and services.audio.\n- Contribute UI by registering in install(): HudWidgets (services.registries.hud.register({ id, slot, order, system:'<id>', component })) for slots topbar-left | topbar-right | hub-banner | hub-sidebar | exam-overlay | results-extra | profile; a HubEntry tile (services.registries.hub.register(...)) and, if your system has a page, a SceneModule (services.registries.scenes.register(...)) with a full-screen scene using @ui-kit Screen/Backdrop. Components are Preact; read state with useSignal from @ui-kit.\n- install() must be idempotent-safe and the returned uninstall must unsubscribe everything. The game must remain fully playable if your folder is deleted.\n- Rewards must scale with LEARNING quality (correctness, efficiency, mastery), never with mere time spent; follow the ethical guardrails (no real money, no punitive loss, streak repair, natural stopping points).\n- Polish: this is where players fall in love \u2014 make every widget and scene gorgeous (glass, glow, motion, count-ups, particles, sound), responsive (375px), accessible.\n- PLAYER-FACING TEXT NEVER CONTAINS SIN WORDS. Use the clinic-themed names.\n- Test logic with vitest using createServices() from @core (no DOM needed for most logic). Preview: create a sandbox page src/app/sandbox/pages/sys-<id>.tsx (default export { id, title, component }) that installs your system into props.services (`yourSystem.install(props.services)` via the folder's default export \u2014 the sandbox page is in src/app so it may import your folder) and fires synthetic events (e.g. fake case:completed with a ScoreBreakdown) with buttons, rendering your HUD widgets and scene \u2014 so reviewers can screenshot it at ?sandbox=page/sys-<id>. Scenes from other teams may still be under construction.\n\n=== YOUR SYSTEM: id 'streaks', player-facing name 'Streaks', internal drive 'gluttony' (never shown) \u2014 folder src/systems/streaks/ ===\nIn-run COMBO: consecutive correct diagnoses build a combo (x1 \u2192 x1.5 \u2192 x2 \u2192 x3) with escalating fire visuals and sound; announce on case:completed; reset on wrong (with a 'combo saved' grace once per run if grade \u2265 B? design sensibly). DAILY STREAK: playing \u2265 1 case per day keeps a flame alive; streak freezes earned by play (auto-used once), milestone rewards (3/7/14/30 days) via currency:grant + reward:granted; never guilt-trip. Near-miss nudges on results ('120 points from your best Rush Hour', 'one more for a x3 combo'). Personal bests per mode. HUD: topbar-right flame with day count; exam-overlay combo meter (subtle, top corner) during runs; results-extra 'Next patient' momentum panel (combo status + one-more nudge; it should not navigate itself \u2014 just display). Hub-sidebar card with streak calendar. No scene required (optional small 'streaks' modal is fine).", "tier": "standard", "start": "review"}, {"key": "sys-collection", "owns": ["src/systems/collection/", "src/app/sandbox/pages/sys-collection.tsx"], "brief": "You build ONE ENGAGEMENT SYSTEM plugin for Lumen. Contract: SystemModule in src/core/systems.ts (id, player-facing name, internal `drive`, color, install(services) \u2192 uninstall). Read docs/ENGAGEMENT_DESIGN.md (internal psychology lens) and docs/research/04-sins-engagement.md for mechanics + ethical guardrails, and docs/GAME_DESIGN.md \u00a77 for your system's player-facing name and scope.\nHow systems plug in (never import other systems/scenes \u2014 boundaries are enforced):\n- Persist state with services.save.slot('sys:<id>', initial, { version }).\n- Listen to bus events (src/core/events.ts): case:started, history:asked, test:completed, diagnosis:submitted, case:completed (has the full ScoreBreakdown), case:failed, mode:started/ended, practice:completed, currency:grant/currency:changed, xp:grant/rank:changed, patient:arriving, app:ready, scene:changed.\n- Announce rewards with bus.emit('reward:granted', {source:'<id>', label, value, icon, color, rarity}) \u2014 the results screen shows them; use toast / achievement:unlocked events for moments; juice with services.fx and services.audio.\n- Contribute UI by registering in install(): HudWidgets (services.registries.hud.register({ id, slot, order, system:'<id>', component })) for slots topbar-left | topbar-right | hub-banner | hub-sidebar | exam-overlay | results-extra | profile; a HubEntry tile (services.registries.hub.register(...)) and, if your system has a page, a SceneModule (services.registries.scenes.register(...)) with a full-screen scene using @ui-kit Screen/Backdrop. Components are Preact; read state with useSignal from @ui-kit.\n- install() must be idempotent-safe and the returned uninstall must unsubscribe everything. The game must remain fully playable if your folder is deleted.\n- Rewards must scale with LEARNING quality (correctness, efficiency, mastery), never with mere time spent; follow the ethical guardrails (no real money, no punitive loss, streak repair, natural stopping points).\n- Polish: this is where players fall in love \u2014 make every widget and scene gorgeous (glass, glow, motion, count-ups, particles, sound), responsive (375px), accessible.\n- PLAYER-FACING TEXT NEVER CONTAINS SIN WORDS. Use the clinic-themed names.\n- Test logic with vitest using createServices() from @core (no DOM needed for most logic). Preview: create a sandbox page src/app/sandbox/pages/sys-<id>.tsx (default export { id, title, component }) that installs your system into props.services (`yourSystem.install(props.services)` via the folder's default export \u2014 the sandbox page is in src/app so it may import your folder) and fires synthetic events (e.g. fake case:completed with a ScoreBreakdown) with buttons, rendering your HUD widgets and scene \u2014 so reviewers can screenshot it at ?sandbox=page/sys-<id>. Scenes from other teams may still be under construction.\n\n=== YOUR SYSTEM: id 'collection', player-facing name 'Gallery', internal drive 'lust' (never shown) \u2014 folder src/systems/collection/ ===\nEvery completed case (correct diagnosis) grants an IRIS CARD: a collectible, procedurally painted iris artwork (use @render paintIrisArt with a seed derived from the case and the patient's irisColor) with rarity by grade (S \u2192 epic/legendary chance), holographic foil shimmer that follows the pointer/tilt, the patient's name, diagnosis name (look it up via services.registries.diagnoses), date, and a teaching pearl on the back (flip animation) \u2014 cards double as flash-cards. Collection progress per diagnosis category, set completion rewards (xp:grant, currency:grant), duplicates upgrade a card's frame (bronze \u2192 silver \u2192 gold \u2192 prismatic). Scene 'gallery': a museum-like gallery with soft spotlights, filter by category/rarity, card inspect modal (3D tilt, flip). HUD: results-extra 'New card!' reveal with a dramatic pack-opening moment; hub-sidebar 'latest acquisition' card. HubEntry 'gallery' with NEW badge.", "tier": "standard", "start": "review"}, {"key": "sys-emergencies", "owns": ["src/systems/emergencies/", "src/app/sandbox/pages/sys-emergencies.tsx"], "brief": "You build ONE ENGAGEMENT SYSTEM plugin for Lumen. Contract: SystemModule in src/core/systems.ts (id, player-facing name, internal `drive`, color, install(services) \u2192 uninstall). Read docs/ENGAGEMENT_DESIGN.md (internal psychology lens) and docs/research/04-sins-engagement.md for mechanics + ethical guardrails, and docs/GAME_DESIGN.md \u00a77 for your system's player-facing name and scope.\nHow systems plug in (never import other systems/scenes \u2014 boundaries are enforced):\n- Persist state with services.save.slot('sys:<id>', initial, { version }).\n- Listen to bus events (src/core/events.ts): case:started, history:asked, test:completed, diagnosis:submitted, case:completed (has the full ScoreBreakdown), case:failed, mode:started/ended, practice:completed, currency:grant/currency:changed, xp:grant/rank:changed, patient:arriving, app:ready, scene:changed.\n- Announce rewards with bus.emit('reward:granted', {source:'<id>', label, value, icon, color, rarity}) \u2014 the results screen shows them; use toast / achievement:unlocked events for moments; juice with services.fx and services.audio.\n- Contribute UI by registering in install(): HudWidgets (services.registries.hud.register({ id, slot, order, system:'<id>', component })) for slots topbar-left | topbar-right | hub-banner | hub-sidebar | exam-overlay | results-extra | profile; a HubEntry tile (services.registries.hub.register(...)) and, if your system has a page, a SceneModule (services.registries.scenes.register(...)) with a full-screen scene using @ui-kit Screen/Backdrop. Components are Preact; read state with useSignal from @ui-kit.\n- install() must be idempotent-safe and the returned uninstall must unsubscribe everything. The game must remain fully playable if your folder is deleted.\n- Rewards must scale with LEARNING quality (correctness, efficiency, mastery), never with mere time spent; follow the ethical guardrails (no real money, no punitive loss, streak repair, natural stopping points).\n- Polish: this is where players fall in love \u2014 make every widget and scene gorgeous (glass, glow, motion, count-ups, particles, sound), responsive (375px), accessible.\n- PLAYER-FACING TEXT NEVER CONTAINS SIN WORDS. Use the clinic-themed names.\n- Test logic with vitest using createServices() from @core (no DOM needed for most logic). Preview: create a sandbox page src/app/sandbox/pages/sys-<id>.tsx (default export { id, title, component }) that installs your system into props.services (`yourSystem.install(props.services)` via the folder's default export \u2014 the sandbox page is in src/app so it may import your folder) and fires synthetic events (e.g. fake case:completed with a ScoreBreakdown) with buttons, rendering your HUD widgets and scene \u2014 so reviewers can screenshot it at ?sandbox=page/sys-<id>. Scenes from other teams may still be under construction.\n\n=== YOUR SYSTEM: id 'emergencies', player-facing name 'Code Red', internal drive 'wrath' (never shown) \u2014 folder src/systems/emergencies/ ===\nOwns the adrenaline layer for emergency cases (case:started with emergency=true / timeLimitSec): exam-overlay widget with a dramatic countdown (Space Grotesk digits, ring that drains, colour shifts to crimson, pulse on last 10s), heartbeat audio that speeds up (services.audio 'heartbeat' at increasing rate; stop on end), red vignette pulses (services.fx.vignette), flashing 'CODE RED' banner on arrival with a short klaxon. It only DISPLAYS time; the exam scene enforces timeout (via services.session.state timeLimitSec + startedAt). On case:completed for an emergency with correct diagnosis + urgency: 'SIGHT SAVED' cinematic finale (hitstop, flash, sparks, big reward), bonus via currency:grant/xp:grant and reward:granted; wrong triage of an emergency \u2192 sober teaching toast about the red flags (no gore). Weekly 'Grand Rounds' challenge card (hub-banner) highlighting one emergency case (deterministic per week) with a bonus. Track emergency stats (saved, avg time) for a profile section. No own scene required (code-red mode already exists).", "tier": "standard", "start": "review"}, {"key": "sys-comfort", "owns": ["src/systems/comfort/", "src/app/sandbox/pages/sys-comfort.tsx"], "brief": "You build ONE ENGAGEMENT SYSTEM plugin for Lumen. Contract: SystemModule in src/core/systems.ts (id, player-facing name, internal `drive`, color, install(services) \u2192 uninstall). Read docs/ENGAGEMENT_DESIGN.md (internal psychology lens) and docs/research/04-sins-engagement.md for mechanics + ethical guardrails, and docs/GAME_DESIGN.md \u00a77 for your system's player-facing name and scope.\nHow systems plug in (never import other systems/scenes \u2014 boundaries are enforced):\n- Persist state with services.save.slot('sys:<id>', initial, { version }).\n- Listen to bus events (src/core/events.ts): case:started, history:asked, test:completed, diagnosis:submitted, case:completed (has the full ScoreBreakdown), case:failed, mode:started/ended, practice:completed, currency:grant/currency:changed, xp:grant/rank:changed, patient:arriving, app:ready, scene:changed.\n- Announce rewards with bus.emit('reward:granted', {source:'<id>', label, value, icon, color, rarity}) \u2014 the results screen shows them; use toast / achievement:unlocked events for moments; juice with services.fx and services.audio.\n- Contribute UI by registering in install(): HudWidgets (services.registries.hud.register({ id, slot, order, system:'<id>', component })) for slots topbar-left | topbar-right | hub-banner | hub-sidebar | exam-overlay | results-extra | profile; a HubEntry tile (services.registries.hub.register(...)) and, if your system has a page, a SceneModule (services.registries.scenes.register(...)) with a full-screen scene using @ui-kit Screen/Backdrop. Components are Preact; read state with useSignal from @ui-kit.\n- install() must be idempotent-safe and the returned uninstall must unsubscribe everything. The game must remain fully playable if your folder is deleted.\n- Rewards must scale with LEARNING quality (correctness, efficiency, mastery), never with mere time spent; follow the ethical guardrails (no real money, no punitive loss, streak repair, natural stopping points).\n- Polish: this is where players fall in love \u2014 make every widget and scene gorgeous (glass, glow, motion, count-ups, particles, sound), responsive (375px), accessible.\n- PLAYER-FACING TEXT NEVER CONTAINS SIN WORDS. Use the clinic-themed names.\n- Test logic with vitest using createServices() from @core (no DOM needed for most logic). Preview: create a sandbox page src/app/sandbox/pages/sys-<id>.tsx (default export { id, title, component }) that installs your system into props.services (`yourSystem.install(props.services)` via the folder's default export \u2014 the sandbox page is in src/app so it may import your folder) and fires synthetic events (e.g. fake case:completed with a ScoreBreakdown) with buttons, rendering your HUD widgets and scene \u2014 so reviewers can screenshot it at ?sandbox=page/sys-<id>. Scenes from other teams may still be under construction.\n\n=== YOUR SYSTEM: id 'comfort', player-facing name 'Lounge', internal drive 'sloth' (never shown) \u2014 folder src/systems/comfort/ ===\nLow-friction comfort & return rewards. DAILY GIFT: once per day a gift box in the lounge/hub-banner (tap to open \u2192 coins/crate via events) with a 7-day escalating calendar. CLINIC EARNINGS WHILE AWAY: the clinic accrues coins slowly while the player is away (capped at e.g. 8h), shown on return as a cosy 'Welcome back, Doctor' modal with a collect button (currency:grant) \u2014 computed from save timestamps + services.clock. COMEBACK BONUS after \u2265 3 days away (warm, no guilt). ONE-TAP RESUME: a hub-banner 'Continue' that starts the most suitable mode (call beginRun(services, modeId) from @core \u2014 prefer 'daily' if not done today, else 'shift'). Scene 'lounge': a cosy, beautiful clinic lounge (rain on the window, warm lamp, plants, a coffee steaming) showing the gift calendar, idle earnings jar, tips of the day (rotating clinical pearls pulled from services.registries.diagnoses), and a 'quiet mode' toggle that switches music to 'zen'. HubEntry 'lounge'. HUD: hub-banner gift/continue banner.", "tier": "standard", "start": "review"}, {"key": "scene-title", "owns": ["src/scenes/title/"], "brief": "You build SCENES (screens) for Lumen. Contract: SceneModule in src/core/ui.ts \u2014 each folder src/scenes/<id>/index.ts(x) default-exports a SceneModule (or array). Scenes get { services, params }. Scenes never import other scenes, systems or minigames: they discover everything through services.registries (minigames, cases, diagnoses, modes, hub entries, hud widgets), render engagement widgets via <HudSlot slot=\"...\"/> from @ui-kit, navigate with services.router.go(id, params), and use the shared run flow helpers in src/core/flow.ts (beginRun, advanceRun, playSingleCase, abandonRun). Read src/core/session.ts (CaseSessionController/RunController), src/core/scoring.ts, src/core/tests.ts (TEST_CATALOG), and the @ui-kit and @render APIs (src/ui-kit/index.ts, src/render/**/index.ts) before you start. Use @ui-kit Screen/Backdrop/Button/GlassPanel/etc. so all screens share one visual language (GAME_DESIGN.md \u00a73). Set `music` on the SceneModule.\nQuality: this is the face of a $1M game \u2014 cinematic, layered depth, parallax, staggered entrance animations, juicy feedback (services.fx / services.audio), responsive down to 375px (phone layouts are a first-class design, not an afterthought), keyboard accessible, reducedMotion honoured. Must work even if engagement systems or some mini-games are missing (empty slots collapse gracefully). Player-facing text: never sin words.\nPreview with ?sandbox=scene/<id>[&param=value] (all plugins load). Other teams may still be building systems/minigames/content in parallel; if something you need is absent, degrade gracefully and note it. For pure logic, add vitest tests.\n\n=== YOUR SCENES ===\nScene 'title' (music 'title'): a breathtaking cinematic opening. A huge living eye centre-stage (use @render drawEye/EyeCanvas with a gorgeous iris) whose gaze follows the cursor/touch, blinks, pupil reacts to a light sweep; observatory-at-midnight backdrop with rain on glass, drifting light motes, slow parallax layers, lens flare; the LUMEN wordmark in Fraunces with a light-sweep shimmer and a subtitle ('The Eye Clinic'); 'Open the clinic' primary button (unlocks audio \u2014 services.audio.unlock() \u2014 plays 'door'/'reveal', zooms INTO the pupil as a transition before router.go('hub')); small settings/credits links. First-time players (settings.onboarded false) get a short, elegant 3-card intro (who you are, how a consult works: history \u2192 tests \u2192 diagnosis & urgency, what you can earn) then set onboarded=true. Keyboard: Enter starts.", "tier": "standard", "start": "review"}, {"key": "scene-hub", "owns": ["src/scenes/hub/"], "brief": "You build SCENES (screens) for Lumen. Contract: SceneModule in src/core/ui.ts \u2014 each folder src/scenes/<id>/index.ts(x) default-exports a SceneModule (or array). Scenes get { services, params }. Scenes never import other scenes, systems or minigames: they discover everything through services.registries (minigames, cases, diagnoses, modes, hub entries, hud widgets), render engagement widgets via <HudSlot slot=\"...\"/> from @ui-kit, navigate with services.router.go(id, params), and use the shared run flow helpers in src/core/flow.ts (beginRun, advanceRun, playSingleCase, abandonRun). Read src/core/session.ts (CaseSessionController/RunController), src/core/scoring.ts, src/core/tests.ts (TEST_CATALOG), and the @ui-kit and @render APIs (src/ui-kit/index.ts, src/render/**/index.ts) before you start. Use @ui-kit Screen/Backdrop/Button/GlassPanel/etc. so all screens share one visual language (GAME_DESIGN.md \u00a73). Set `music` on the SceneModule.\nQuality: this is the face of a $1M game \u2014 cinematic, layered depth, parallax, staggered entrance animations, juicy feedback (services.fx / services.audio), responsive down to 375px (phone layouts are a first-class design, not an afterthought), keyboard accessible, reducedMotion honoured. Must work even if engagement systems or some mini-games are missing (empty slots collapse gracefully). Player-facing text: never sin words.\nPreview with ?sandbox=scene/<id>[&param=value] (all plugins load). Other teams may still be building systems/minigames/content in parallel; if something you need is absent, degrade gracefully and note it. For pure logic, add vitest tests.\n\n=== YOUR SCENES ===\nScene 'hub' (music 'hub'): the Lumen lobby \u2014 the place players return to 100 times, so it must be irresistible. Top bar with <HudSlot slot='topbar-left'/> and 'topbar-right', player name, settings button. Hero: <HudSlot slot='hub-banner'/> area, then MODE CARDS from services.registries.modes (sorted by order; title, tagline, icon, accent glow, rules summary like '5 patients' / 'Endless \u00b7 3 lives' / timers; locked state with reason from mode.locked(services)); clicking starts beginRun(services, mode.id) with a door-opening transition and a 'patient:arriving' moment. Below/side: WING TILES from services.registries.hub (HubEntry: icon, title, subtitle, accent, badge(), locked()) \u2192 router.go(entry.sceneId, entry.params); <HudSlot slot='hub-sidebar'/>. Also tiles for core scenes: Arcade ('arcade'), Codex ('codex'), Profile ('profile') (only if those scenes are registered). Ambient life: a waiting-room vignette with 2-3 animated patient silhouettes/avatars (from @render) idling, rain on windows, a clock. Phone layout: stacked, thumb-reachable.", "tier": "standard", "start": "review"}, {"key": "scene-exam", "owns": ["src/scenes/exam/"], "brief": "You build SCENES (screens) for Lumen. Contract: SceneModule in src/core/ui.ts \u2014 each folder src/scenes/<id>/index.ts(x) default-exports a SceneModule (or array). Scenes get { services, params }. Scenes never import other scenes, systems or minigames: they discover everything through services.registries (minigames, cases, diagnoses, modes, hub entries, hud widgets), render engagement widgets via <HudSlot slot=\"...\"/> from @ui-kit, navigate with services.router.go(id, params), and use the shared run flow helpers in src/core/flow.ts (beginRun, advanceRun, playSingleCase, abandonRun). Read src/core/session.ts (CaseSessionController/RunController), src/core/scoring.ts, src/core/tests.ts (TEST_CATALOG), and the @ui-kit and @render APIs (src/ui-kit/index.ts, src/render/**/index.ts) before you start. Use @ui-kit Screen/Backdrop/Button/GlassPanel/etc. so all screens share one visual language (GAME_DESIGN.md \u00a73). Set `music` on the SceneModule.\nQuality: this is the face of a $1M game \u2014 cinematic, layered depth, parallax, staggered entrance animations, juicy feedback (services.fx / services.audio), responsive down to 375px (phone layouts are a first-class design, not an afterthought), keyboard accessible, reducedMotion honoured. Must work even if engagement systems or some mini-games are missing (empty slots collapse gracefully). Player-facing text: never sin words.\nPreview with ?sandbox=scene/<id>[&param=value] (all plugins load). Other teams may still be building systems/minigames/content in parallel; if something you need is absent, degrade gracefully and note it. For pure logic, add vitest tests.\n\n=== YOUR SCENES ===\nScene 'exam' (music 'exam'; params { caseId, modeId }): THE core gameplay screen \u2014 spec in docs/GAME_DESIGN.md \u00a74 'Exam room'. Read the case from services.registries.cases and live state from services.session.state (start a session yourself only if none is active for this caseId \u2014 e.g. opened via sandbox). Layout (desktop 3 columns; phone = tabs Patient / Tests / Chart with a sticky Diagnose button): PATIENT column \u2014 animated <PatientAvatar> (expression reacts: pain for painful conditions, relieved after diagnosis, worried by default; external signs from findings.external), name/age/occupation/personality card, chief complaint in a typewriter SpeechBubble, triage note card; HISTORY panel \u2014 question chips grouped by category; clicking calls services.session.ask(id) and the answer appears in the patient's voice (speech bubble + chat log); KEY questions are not labelled as such. INSTRUMENT TRAY \u2014 one tool per registered mini-game (services.registries.minigames, ordered by TEST_CATALOG category), showing icon, name, minutes; done tests get a check; clicking opens a large modal stage and mounts the mini-game: mg.mount(hostEl, ctx, done) with ctx {testId, patient, findings, mode:'case', difficulty from case.difficulty, rng: services.rng.fork(caseId+testId), audio, fx, reducedMotion}; on done(result) \u2192 services.session.recordTest(result), close stage with a satisfying 'chart updated' flourish (findings fly into the chart); always call the cleanup. If the current mode's rules.autoRun !== false, offer 'Ask the technician' per tool: instant result from mg.report(findings, patient) with accuracy 0.5 & autoRun true. Tests for which no mini-game is registered are simply not shown. CHART column \u2014 RevealedFinding rows grouped by test with normal/abnormal/critical colour + icon, eye badge, newly added rows glow. TOP BAR \u2014 case progress (e.g. patient 2/5 from services.run.state), clinic minutes used, elapsed timer; <HudSlot slot='exam-overlay'/>, hint button (services.session.useHint() + bus 'hint:used'; reveals one helpful nudge e.g. an essential test not yet done or a key question category \u2014 costs efficiency). Emergency enforcement: if session.timeLimitSec is set and time runs out \u2192 services.session.fail('timeout') and go to 'results' with { caseId, modeId, timeout: true }. DIAGNOSE \u2014 opens a luxurious full-screen DIAGNOSIS BOARD: the case's diagnosis + differentials shuffled (deterministic) as elegant cards (diagnosis name from registries.diagnoses with category glyph; no summaries that give it away), an URGENCY selector (routine / soon / urgent / emergency with clear plain-language descriptions), a confirmation with a dramatic stamp; then services.session.submit(dx, urgency) \u2192 router.go('results', { caseId, modeId }). Patient enters with a door/walk-in animation on mount. Robust: mini-game throwing in mount must not crash the scene (catch, show error, allow skip).\n\nEXTRA (from our research \u2014 learning science): (a) WORKING DIFFERENTIAL: a compact 'Suspects' board where the player can pin up to 4 suspected diagnoses at any time (searchable picker over services.registries.diagnoses) and reorder them; it persists for the case and pinned suspects that are later ruled-in/out by findings are simply the player's notes (no auto-hints). (b) On the diagnosis board, after choosing diagnosis + urgency, the player rates CONFIDENCE \u2014 'Guessing' / 'Fairly sure' / 'Certain' \u2014 passed as services.session.submit(dx, urgency, confidence). (c) Diagnosis cards should NOT show a summary that gives the answer away; show name + category only.", "tier": "heavy", "start": "review"}, {"key": "scene-results", "owns": ["src/scenes/results/"], "brief": "You build SCENES (screens) for Lumen. Contract: SceneModule in src/core/ui.ts \u2014 each folder src/scenes/<id>/index.ts(x) default-exports a SceneModule (or array). Scenes get { services, params }. Scenes never import other scenes, systems or minigames: they discover everything through services.registries (minigames, cases, diagnoses, modes, hub entries, hud widgets), render engagement widgets via <HudSlot slot=\"...\"/> from @ui-kit, navigate with services.router.go(id, params), and use the shared run flow helpers in src/core/flow.ts (beginRun, advanceRun, playSingleCase, abandonRun). Read src/core/session.ts (CaseSessionController/RunController), src/core/scoring.ts, src/core/tests.ts (TEST_CATALOG), and the @ui-kit and @render APIs (src/ui-kit/index.ts, src/render/**/index.ts) before you start. Use @ui-kit Screen/Backdrop/Button/GlassPanel/etc. so all screens share one visual language (GAME_DESIGN.md \u00a73). Set `music` on the SceneModule.\nQuality: this is the face of a $1M game \u2014 cinematic, layered depth, parallax, staggered entrance animations, juicy feedback (services.fx / services.audio), responsive down to 375px (phone layouts are a first-class design, not an afterthought), keyboard accessible, reducedMotion honoured. Must work even if engagement systems or some mini-games are missing (empty slots collapse gracefully). Player-facing text: never sin words.\nPreview with ?sandbox=scene/<id>[&param=value] (all plugins load). Other teams may still be building systems/minigames/content in parallel; if something you need is absent, degrade gracefully and note it. For pure logic, add vitest tests.\n\n=== YOUR SCENES ===\nScenes 'results' (music 'results'; params { caseId, modeId, timeout? }) and 'run-summary' (params { modeId, snapshot }). RESULTS: read services.session.state.submitted.score (ScoreBreakdown) \u2014 or the timeout case. On mount, if a run is active (services.run.state), call services.run.report(caseId, score) EXACTLY ONCE (guard against re-renders). Choreography: (1) verdict \u2014 the diagnosis card flips: correct = golden glow + hitstop + sparks + 'success'; wrong = gentle shake + reveal of the correct diagnosis with what they picked crossed out; (2) GradeStamp slams in; (3) score parts count up one by one with labels (Diagnosis, Triage urgency, Essential work-up, Efficiency, History taking, Test technique, Speed) and a total; (4) teaching: correct diagnosis summary, key findings, pearls (from registries.diagnoses), the case's teachingPoints, redFlags, management, urgency explanation; 'What you missed': essential tests skipped, key history questions unasked (list them with their answers \u2014 retrieval \u2192 elaboration), unnecessary tests; (5) rewards: every 'reward:granted' emitted while the case was active is buffered in services.session.state.rewards (they fire synchronously on submit, before this scene mounts) \u2014 cascade them in as RewardChips with sound, and also subscribe to services.bus 'reward:granted' for any that arrive later; render <HudSlot slot='results-extra'/> where engagement systems show their own panels (XP, coins, cards, rivals, streak). Timeout: services.session.state.failed === 'timeout' \u2192 a sober 'Out of time' verdict with the correct answer and teaching. (6) buttons: 'Next patient' \u2192 advanceRun(services) (if a run is active) with a big inviting style; 'Codex entry' \u2192 router.go('codex', { diagnosisId }); 'Back to clinic' \u2192 abandonRun or hub. RUN-SUMMARY: gorgeous end-of-run report: total score count-up, patients table (grade per case), best case, accuracy %, combo peak, personal-best flag, <HudSlot slot='results-extra'/>, buttons Play again (beginRun same mode) / Back to clinic.\n\nEXTRA: show the player's CONFIDENCE (services.session.state.submitted.confidence) next to the verdict. 'Certain' + wrong = a prominent but kind 'Confidently wrong \u2014 this one will come back for review' callout (the highest-value learning moment); 'Guessing' + right = 'Lucky? Lock it in' nudge to read the key findings. End the teaching section with a one-line REFLECTION prompt card ('What clinched it?') showing the 2 most discriminating findings from the chart.", "tier": "standard", "start": "review"}, {"key": "scene-meta", "owns": ["src/scenes/arcade/", "src/scenes/codex/", "src/scenes/profile/", "src/scenes/settings/"], "brief": "You build SCENES (screens) for Lumen. Contract: SceneModule in src/core/ui.ts \u2014 each folder src/scenes/<id>/index.ts(x) default-exports a SceneModule (or array). Scenes get { services, params }. Scenes never import other scenes, systems or minigames: they discover everything through services.registries (minigames, cases, diagnoses, modes, hub entries, hud widgets), render engagement widgets via <HudSlot slot=\"...\"/> from @ui-kit, navigate with services.router.go(id, params), and use the shared run flow helpers in src/core/flow.ts (beginRun, advanceRun, playSingleCase, abandonRun). Read src/core/session.ts (CaseSessionController/RunController), src/core/scoring.ts, src/core/tests.ts (TEST_CATALOG), and the @ui-kit and @render APIs (src/ui-kit/index.ts, src/render/**/index.ts) before you start. Use @ui-kit Screen/Backdrop/Button/GlassPanel/etc. so all screens share one visual language (GAME_DESIGN.md \u00a73). Set `music` on the SceneModule.\nQuality: this is the face of a $1M game \u2014 cinematic, layered depth, parallax, staggered entrance animations, juicy feedback (services.fx / services.audio), responsive down to 375px (phone layouts are a first-class design, not an afterthought), keyboard accessible, reducedMotion honoured. Must work even if engagement systems or some mini-games are missing (empty slots collapse gracefully). Player-facing text: never sin words.\nPreview with ?sandbox=scene/<id>[&param=value] (all plugins load). Other teams may still be building systems/minigames/content in parallel; if something you need is absent, degrade gracefully and note it. For pure logic, add vitest tests.\n\n=== YOUR SCENES ===\nFour supporting scenes (separate folders). ARCADE 'arcade' (music 'zen'): a beautiful grid of every registered mini-game that has practice(); pick difficulty (Easy/Clinical/Expert); mounts the mini-game in a stage with ctx.mode 'practice' and a fresh scenario from mg.practice(rng, difficulty); on done emits bus 'practice:completed' and shows accuracy, best score per game (save slot 'scene:arcade'), 'Again' button. CODEX 'codex' (params { diagnosisId? }): an illuminated-manuscript-meets-modern encyclopedia of services.registries.diagnoses grouped by category; entries are locked (elegant silhouette) until services.learning.seen(id) is true (or always open in a 'study' toggle); detail view with summary, key findings, pearls, typical urgency, reference link, mastery ring, and 'Practise a case' (playSingleCase with a case whose diagnosis matches). PROFILE 'profile': player name (editable \u2192 settings.playerName), learning stats (services.learning.stats(): diagnoses seen / mastered / due) and <HudSlot slot='profile'/> where engagement systems contribute their sections (rank, coins, streaks, emergencies). SETTINGS 'settings': master/sfx/music sliders (live), reduced motion, metric VA, high contrast, player name, export save (download JSON via services.save.exportAll()), import save (file input \u2192 importAll \u2192 reload), reset progress (confirm modal), credits & clinical disclaimer ('educational game, not medical advice'). All four: @ui-kit Screen with back button, gorgeous and consistent.", "tier": "standard", "start": "review"}]
const UNITS = (args && args.only) ? LIBRARY.filter(u => args.only.includes(u.key)) : LIBRARY

const PREAMBLE = `You are a senior engineer + game artist on "Lumen — The Eye Clinic", a browser game (Vite + TypeScript + Preact, procedural art, no image assets) that teaches optometry. The owner wants it to look and feel like a $1M production. Repository: ${ROOT}.

READ FIRST: ${ROOT}/docs/ARCHITECTURE.md, ${ROOT}/docs/GAME_DESIGN.md, and the contracts in ${ROOT}/src/core/*.ts (especially the files relevant to you). If research notes exist in ${ROOT}/docs/research/ and docs/SINS.md, skim the parts relevant to your module.

PLAYER-FACING RULE (critical): players must NEVER see the words sin/sins/deadly/vice, sin names (pride, greed, envy, gluttony, lust, wrath, sloth) or religious framing anywhere in UI text, titles, achievements, tooltips, CSS class names visible as text, or console output. The seven sins are only an internal psychology lens (docs/ENGAGEMENT_DESIGN.md). Use the neutral clinic-themed names from docs/GAME_DESIGN.md.

HARD RULES (a reviewer will reject violations):
- Only create/modify files inside the paths you OWN (listed below). Other engineers are editing other folders concurrently. Never edit src/core, src/app (except your own sandbox page file if listed), package.json, or anything else not yours. If you truly need a core contract change, do NOT make it — put it in coreRequests in your final output and work around it.
- NEVER run git commands that change state (no git add/commit/stash/checkout/reset/clean). Read-only git (status/diff/log) is fine.
- Respect module boundaries (docs/ARCHITECTURE.md). Import only from allowed layers via aliases (@core, @ui-kit, @render). Only third-party package allowed: preact. Run: node scripts/check-boundaries.mjs (violations elsewhere that are not yours can be ignored).
- Typecheck only your module: npm run check:mod -- <your paths>. It must report zero errors in your paths.
- Write focused unit tests (vitest, *.test.ts next to the code) for any non-trivial logic; run them with: npx vitest run <your dir>.
- A Vite dev server is ALREADY running at http://localhost:5173 with hot reload. Do NOT start another server and do NOT kill it. Screenshot your work with: node scripts/shot.cjs "<query>" /tmp/shots/<name>.png [--mobile] [--click "<css selector>"] [--wait 1500] then LOOK at the PNG with the Read tool. Iterate on visuals until they are genuinely beautiful. Check mobile (375px) too. The script prints console errors — fix any from your module.
- Quality bar: luxurious "stained glass at midnight" art direction from GAME_DESIGN.md, smooth eased animation, juicy feedback, sound hooks via the AudioPort/FxPort (ctx.audio / services.audio, ctx.fx / services.fx), keyboard + touch support, prefers reduced motion honoured, no console errors, clean up all listeners/RAF/timers on unmount. Clinically accurate — an optometrist will review it.
- Use design tokens / components from @ui-kit when they exist (read src/ui-kit/ to see what is available). Keep files reasonably small and cohesive.

TOKEN BUDGET: be economical — read only the files you need, take at most ~6 screenshots per pass (desktop + one mobile is usually enough), do not paste large files into your reasoning, and stop iterating once the bar is met.

Your final answer is consumed by an orchestrator (not a human): return it via the structured output.`

const BUILD_SCHEMA = {
  type: 'object',
  properties: {
    summary: { type: 'string', description: 'What you built, key design decisions' },
    filesTouched: { type: 'array', items: { type: 'string' } },
    api: { type: 'string', description: 'Public API / exports other modules can use, with signatures' },
    sandboxUrls: { type: 'array', items: { type: 'string' }, description: 'Query strings to view the work, e.g. ?sandbox=minigame/tonometry' },
    coreRequests: { type: 'array', items: { type: 'string' } },
    knownIssues: { type: 'array', items: { type: 'string' } },
  },
  required: ['summary', 'filesTouched', 'api', 'sandboxUrls', 'coreRequests', 'knownIssues'],
}

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    verdict: { type: 'string', enum: ['pass', 'revise'] },
    scores: {
      type: 'object',
      properties: {
        visualPolish: { type: 'number' },
        functionality: { type: 'number' },
        clinicalAccuracy: { type: 'number' },
        modularity: { type: 'number' },
        codeQuality: { type: 'number' },
        accessibilityResponsive: { type: 'number' },
      },
      required: ['visualPolish', 'functionality', 'clinicalAccuracy', 'modularity', 'codeQuality', 'accessibilityResponsive'],
    },
    mustFix: { type: 'array', items: { type: 'string' }, description: 'Concrete, actionable defects with file paths. Empty if pass.' },
    niceToHave: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
  },
  required: ['verdict', 'scores', 'mustFix', 'niceToHave', 'summary'],
}

function ownership(u) {
  return `YOU OWN (may write only here): ${u.owns.join(', ')}`
}

function buildPrompt(u) {
  return `${PREAMBLE}\n\n=== YOUR MODULE: ${u.key} ===\n${ownership(u)}\n\n${u.brief}`
}

function reviewPrompt(u, report, round) {
  return `You are a merciless, senior reviewer (a mix of AAA game art director, staff engineer, and practising optometrist) on "Lumen", a browser game teaching optometry that must look and feel like a $1M production. Repository: ${ROOT}. Read docs/ARCHITECTURE.md and docs/GAME_DESIGN.md first.

You are reviewing module "${u.key}" (review round ${round}). The builder owns: ${u.owns.join(', ')}.
The module's brief was:
---
${u.brief}
---
The builder reports:
${JSON.stringify(report, null, 2)}

DO NOT EDIT ANY FILES. Investigate and judge:
1. Read every file in the owned paths.
2. Run: npm run check:mod -- ${u.owns.filter(p => p.startsWith('src/') && !p.includes('sandbox')).join(' ')} ; node scripts/check-boundaries.mjs ; npx vitest run ${u.owns.filter(p => p.startsWith('src/') && !p.includes('sandbox')).join(' ')} (if tests exist).
3. A dev server runs at http://localhost:5173 (do not start/kill servers). Screenshot with node scripts/shot.cjs "<query>" /tmp/shots/review-${u.key}-<n>.png [--mobile] [--click "<css>"] [--wait 1500] and LOOK at each PNG with the Read tool. Exercise the real interactions (click through with --click, or write a small throwaway Playwright script in /tmp using require('playwright') to drive it step by step). Check desktop 1440x900 AND mobile.
4. Score 1-10 each: visualPolish (would this impress in a $1M game? depth, light, typography, motion, juice — be harsh; programmer-art or flat default-looking UI is <= 5), functionality (does it fully work end-to-end, calls done() exactly once, no console errors, cleanup), clinicalAccuracy (real values/grading/behaviour; 10 if not applicable), modularity (only owned paths touched, contracts honoured, no cross-plugin imports, swappable), codeQuality (readable, typed, tested, no dead code, no leaks), accessibilityResponsive (keyboard, touch, 375px mobile, reduced motion, contrast).
5. Also grep the owned paths for player-visible sin language (sin, sins, deadly, pride, greed, envy, gluttony, lust, wrath, sloth) — any player-visible occurrence is a must-fix (internal 'drive' metadata fields are fine).
6. verdict = "pass" only if EVERY score >= 8 and there are no must-fix defects. Otherwise "revise", with mustFix items that are specific and actionable (what is wrong, where, what "good" looks like). Do not pass work out of politeness — the owner explicitly wants sub-par work sent back.`
}

function fixPrompt(u, report, review, round) {
  return `${buildPrompt(u)}\n\n=== REVISION ROUND ${round} ===\nYou (or a previous engineer) already built this module; the code is on disk. A strict reviewer rejected it. Previous build report:\n${JSON.stringify(report, null, 2)}\n\nReviewer verdict:\n${JSON.stringify(review, null, 2)}\n\nFix EVERY mustFix item, and as many niceToHave items as are worthwhile. Raise the visual polish further where the reviewer scored it below 9. Re-verify with checks and screenshots before finishing.`
}

// Model routing — no agent inherits the orchestrator's model.
const HEAVY = (u) => u.tier === 'heavy'
const M = {
  build: (u) => ({ model: 'sonnet', effort: HEAVY(u) ? 'high' : 'medium' }),
  revise: (u) => ({ model: 'sonnet', effort: HEAVY(u) ? 'high' : 'medium' }),
  review: (u) => ({ model: 'sonnet', effort: 'medium' }),
  checks: () => ({ model: 'haiku', effort: 'low' }),
}

const CHECK_SCHEMA = {
  type: 'object',
  properties: {
    ok: { type: 'boolean' },
    failures: { type: 'array', items: { type: 'string' }, description: 'Exact error lines (file:line message), max 30' },
  },
  required: ['ok', 'failures'],
}

function srcPaths(u) { return u.owns.filter(p => p.startsWith('src/') && !p.includes('sandbox')).join(' ') }

function checksPrompt(u) {
  return `Mechanical verification only — do not edit files, do not judge design. Repository: ${ROOT}. Run these commands and report every failure that concerns the paths ${u.owns.join(', ')}:
1. cd ${ROOT} && npm run check:mod -- ${srcPaths(u)}
2. node scripts/check-boundaries.mjs   (only violations in the paths above count)
3. npx vitest run ${srcPaths(u)}   ("No test files found" is a failure only if the module has non-trivial logic files)
4. grep -rniE "\\b(sins?|deadly|pride|greed|envy|gluttony|lust|wrath|sloth)\\b" ${srcPaths(u)} — a hit is a failure ONLY if it is player-visible text (UI strings, titles, toasts, achievements); ignore 'drive:' metadata fields, comments, and identifiers.
ok = true when there are no failures.`
}

async function runUnit(u) {
  let report
  if (u.start === 'review') {
    report = { summary: 'Built in an earlier session; the code on disk is the deliverable. Review it as-is.', filesTouched: u.owns, api: 'see code', sandboxUrls: u.sandboxUrls || [], coreRequests: [], knownIssues: [] }
  } else {
    report = await agent(buildPrompt(u) + (u.start === 'continue' ? '\n\nNOTE: a previous engineer started this module and was interrupted; partial code is on disk in your folders. Read it, keep what is good, and finish the job.' : ''), { label: `build:${u.key}`, phase: 'Build', schema: BUILD_SCHEMA, ...M.build(u) })
    if (!report) return { key: u.key, status: 'build-failed' }
  }
  let review = null
  // Optional: carry a previous critic's verdict straight into a revision (saves a fresh review).
  const prior = args && args.priorReview && args.priorReview[u.key]
  if (prior) {
    const fixed = await agent(fixPrompt(u, report, prior, 0), { label: `revise:${u.key}#0`, phase: 'Revise', schema: BUILD_SCHEMA, ...M.revise(u) })
    if (fixed) report = fixed
  }
  for (let round = 1; round <= MAX_FIX_ROUNDS + 1; round++) {
    const chk = await agent(checksPrompt(u), { label: `checks:${u.key}#${round}`, phase: 'Checks', schema: CHECK_SCHEMA, ...M.checks() })
    // Drop gate false positives (e.g. Math.sin identifiers the reporter itself marked as ignorable).
    if (chk) chk.failures = (chk.failures || []).filter(f => !/not a failure|ignored|Math\.sin|identifier/i.test(f))
    if (chk && chk.failures.length) {
      log(`${u.key} round ${round}: mechanical checks failed (${chk.failures.length}) — straight to revise`)
      if (round > MAX_FIX_ROUNDS) { review = { verdict: 'revise', scores: null, mustFix: chk.failures, niceToHave: [], summary: 'mechanical checks failing' }; break }
      const mech = { verdict: 'revise', scores: null, mustFix: chk.failures, niceToHave: [], summary: 'Mechanical checks failed: fix these first (type errors / boundary violations / failing tests / player-visible forbidden words).' }
      const fixed = await agent(fixPrompt(u, report, mech, round), { label: `revise:${u.key}#${round}`, phase: 'Revise', schema: BUILD_SCHEMA, ...M.revise(u) })
      if (fixed) report = fixed
      continue
    }
    review = await agent(reviewPrompt(u, report, round), { label: `review:${u.key}#${round}`, phase: 'Review', schema: REVIEW_SCHEMA, ...M.review(u) })
    if (!review) break
    const sc = review.scores
    const minScore = Math.min(sc.visualPolish, sc.functionality, sc.clinicalAccuracy, sc.modularity, sc.codeQuality, sc.accessibilityResponsive)
    log(`${u.key} round ${round}: ${review.verdict} (min score ${minScore}, ${review.mustFix.length} must-fix)`)
    if (review.verdict === 'pass' && minScore >= 8) return { key: u.key, status: 'passed', rounds: round, report, review }
    if (round > MAX_FIX_ROUNDS) break
    const fixed = await agent(fixPrompt(u, report, review, round), { label: `revise:${u.key}#${round}`, phase: 'Revise', schema: BUILD_SCHEMA, ...M.revise(u) })
    if (fixed) report = fixed
  }
  return { key: u.key, status: 'needs-attention', report, review }
}

const results = await pipeline(UNITS, (u) => runUnit(u))
return results.filter(Boolean).map(r => ({
  key: r.key,
  status: r.status,
  rounds: r.rounds,
  scores: r.review && r.review.scores,
  openMustFix: r.status === 'passed' ? [] : (r.review && r.review.mustFix) || [],
  api: r.report && r.report.api,
  sandboxUrls: r.report && r.report.sandboxUrls,
  coreRequests: r.report && r.report.coreRequests,
  knownIssues: r.report && r.report.knownIssues,
}))
